window.AZ900_BANK=[{"id":"D1-001","d":"cloud-concepts","t":"共享责任模型","k":"single","q":"在共享责任模型中，无论采用 IaaS、PaaS 还是 SaaS，下列哪一项始终由客户负责？","o":{"A":"物理数据中心的门禁与安保","B":"存储在云中的信息与数据","C":"物理网络设备","D":"虚拟机监控程序（Hypervisor）"},"a":["B"],"e":"共享责任模型里有三类责任永远属于客户，不随服务类型改变：①信息与数据（Information and data）②设备（移动设备和 PC）③账户与标识（Accounts and identities）。数据是你的资产，云厂商不会替你决定数据内容、分类和访问授权。反过来，物理主机、物理网络、物理数据中心这三项永远由 Microsoft 负责。","r":{"A":"物理数据中心的安保始终由 Microsoft 负责，客户无法也不需要管理。","C":"物理网络设备属于 Microsoft 永远负责的范畴。","D":"Hypervisor 属于云平台基础设施，即使在 IaaS 中也由 Microsoft 维护，客户只管虚拟机内部。"},"rt":"共享责任模型 - Azure 安全基础","ru":"https://learn.microsoft.com/azure/security/fundamentals/shared-responsibility"},{"id":"D1-002","d":"cloud-concepts","t":"共享责任模型","k":"single","q":"某公司在 Azure 上使用 IaaS（虚拟机）运行业务系统。给虚拟机操作系统打安全补丁是谁的责任？","o":{"A":"Microsoft","B":"客户","C":"由 Microsoft 和客户共同承担，Microsoft 主导","D":"取决于虚拟机所在的区域"},"a":["B"],"e":"IaaS 中，Microsoft 只负责到物理层和虚拟化层；客户机操作系统（Guest OS）的安装、配置、补丁、加固全部由客户负责。这正是 IaaS 与 PaaS 最典型的区别之一——在 PaaS 中操作系统由 Microsoft 维护。","r":{"A":"Microsoft 只在 PaaS/SaaS 中负责操作系统；IaaS 的客户机 OS 归客户。","C":"操作系统补丁在 IaaS 中是客户单方责任，不是共担项。","D":"责任划分由服务类型（IaaS/PaaS/SaaS）决定，与区域无关。"},"rt":"共享责任模型 - 按服务类型划分","ru":"https://learn.microsoft.com/azure/security/fundamentals/shared-responsibility"},{"id":"D1-003","d":"cloud-concepts","t":"共享责任模型","k":"multi","q":"在共享责任模型中，下列哪两项始终由 Microsoft 负责？（选两项）","o":{"A":"物理主机","B":"账户与标识","C":"物理数据中心","D":"应用程序代码"},"a":["A","C"],"e":"永远由 Microsoft 负责的三项是：物理主机（Physical hosts）、物理网络（Physical network）、物理数据中心（Physical datacenter）。这三项统称为云的物理基础设施，任何服务模型下客户都接触不到。","r":{"B":"账户与标识是客户永远的责任——建哪些账号、给谁什么权限由客户决定。","D":"应用程序代码在 IaaS/PaaS 中主要由客户负责，只有 SaaS 中才由 Microsoft 负责。"},"rt":"共享责任模型 - Azure 安全基础","ru":"https://learn.microsoft.com/azure/security/fundamentals/shared-responsibility"},{"id":"D1-004","d":"cloud-concepts","t":"共享责任模型","k":"single","q":"贵公司使用 Microsoft 365（SaaS）。谁负责维护该应用程序本身的代码和运行环境？","o":{"A":"客户","B":"Microsoft","C":"客户的 IT 外包商","D":"客户与 Microsoft 平分"},"a":["B"],"e":"在 SaaS 中，Microsoft 负责应用程序、运行时、操作系统、虚拟化和物理设施；客户只负责数据、设备、账户与标识（以及部分标识与目录基础结构、网络控制的共担部分）。这就是 SaaS 客户管理负担最小的原因。","r":{"A":"SaaS 客户无法接触应用代码，只能配置使用方式。","C":"外包商也只是代客户履行客户那部分责任，应用本身仍归 Microsoft。","D":"SaaS 中应用程序是 Microsoft 单方责任，不是共担。"},"rt":"共享责任模型 - SaaS 责任划分","ru":"https://learn.microsoft.com/azure/security/fundamentals/shared-responsibility"},{"id":"D1-005","d":"cloud-concepts","t":"共享责任模型","k":"single","q":"下列哪一项责任会随着服务类型（IaaS→PaaS→SaaS）的不同而在客户与 Microsoft 之间发生变化？","o":{"A":"物理数据中心","B":"操作系统","C":"信息与数据","D":"账户与标识"},"a":["B"],"e":"操作系统是典型的「随服务类型变化」的责任项：IaaS 由客户负责，PaaS 和 SaaS 由 Microsoft 负责。同类的还有网络控制、应用程序、标识与目录基础结构。","r":{"A":"物理数据中心永远是 Microsoft 的责任，不随服务类型变化。","C":"信息与数据永远是客户的责任，不随服务类型变化。","D":"账户与标识永远是客户的责任，不随服务类型变化。"},"rt":"共享责任模型 - 责任随服务类型变化","ru":"https://learn.microsoft.com/azure/security/fundamentals/shared-responsibility"},{"id":"D1-006","d":"cloud-concepts","t":"共享责任模型","k":"single","q":"采用共享责任模型最主要的业务好处是什么？","o":{"A":"客户可以把所有安全责任转移给云提供商","B":"明确划分双方职责，客户可以把精力集中在自己的数据和业务上","C":"云提供商可以访问客户数据以提供支持","D":"客户不再需要任何安全人员"},"a":["B"],"e":"共享责任模型的价值在于「责任边界清晰」：云提供商承担物理和平台层的繁重运维，客户专注于数据、身份和业务逻辑。它不是免责协议——客户对自己那部分（尤其是数据和身份）依然完全负责。","r":{"A":"安全责任永远无法完全转移，数据和身份始终是客户的责任。","C":"共享责任模型不授予提供商访问客户数据的权利，那是隐私与合规问题。","D":"客户仍需管理身份、访问和数据保护，安全人员依然必要。"},"rt":"共享责任模型 - Azure 安全基础","ru":"https://learn.microsoft.com/azure/security/fundamentals/shared-responsibility"},{"id":"D1-007","d":"cloud-concepts","t":"共享责任模型","k":"single","q":"某公司把本地 SQL Server 迁移到 Azure SQL 数据库（PaaS）。迁移后，数据库引擎的版本升级和补丁由谁负责？","o":{"A":"客户的 DBA 团队","B":"Microsoft","C":"客户需要提交工单请求 Microsoft 执行","D":"由订阅类型决定"},"a":["B"],"e":"Azure SQL 数据库是 PaaS，底层操作系统和数据库引擎的修补、升级、备份基础设施都由 Microsoft 托管。客户负责的是数据本身、架构设计、访问权限和查询性能。这正是 PaaS 相对 IaaS（在 VM 上自建 SQL Server）的核心优势。","r":{"A":"PaaS 下 DBA 不再负责引擎补丁，这部分工作被平台接管。","C":"补丁是平台自动进行的，不需要客户提交工单。","D":"责任划分由服务类型决定，与订阅类型（如即用即付、EA）无关。"},"rt":"共享责任模型 - PaaS 责任划分","ru":"https://learn.microsoft.com/azure/security/fundamentals/shared-responsibility"},{"id":"D1-008","d":"cloud-concepts","t":"共享责任模型","k":"truefalse","q":"判断：在所有云服务模型中，配置哪些用户可以访问资源（访问授权）都是客户的责任。","o":{"A":"正确","B":"错误"},"a":["A"],"e":"正确。「账户与标识（Accounts and identities）」是客户永远的责任。无论 IaaS、PaaS 还是 SaaS，创建哪些账号、分配什么角色、授予什么访问权限，都由客户自行决定和承担后果。","r":{"B":"这是常见误区：即便在 SaaS 中 Microsoft 托管了一切基础设施，用户账号与权限仍由客户管理。"},"rt":"共享责任模型 - Azure 安全基础","ru":"https://learn.microsoft.com/azure/security/fundamentals/shared-responsibility"},{"id":"D1-009","d":"cloud-concepts","t":"云部署模型","k":"single","q":"哪种云部署模型可以让组织把现有本地数据中心与 Azure 结合使用，按需把部分工作负载放到云中？","o":{"A":"公有云","B":"私有云","C":"混合云","D":"多云"},"a":["C"],"e":"混合云（Hybrid cloud）同时使用本地（私有）环境和公有云，两者互联。典型场景包括：把敏感数据留在本地而把前端放到云上、用云做灾难恢复目标、以及「云爆发」（cloud bursting，本地资源不够时临时借用云资源）。","r":{"A":"公有云指全部资源由第三方提供商托管，不包含本地数据中心。","B":"私有云是组织自己独占使用的云环境，不涉及与公有云的结合。","D":"多云指同时使用两个或以上不同的云提供商（如 Azure + AWS），描述的不是「本地 + 云」。"},"rt":"云计算的部署模型","ru":"https://learn.microsoft.com/training/modules/describe-cloud-compute/"},{"id":"D1-010","d":"cloud-concepts","t":"云部署模型","k":"single","q":"某公司同时使用 Microsoft Azure 和 Amazon Web Services 承载不同的应用。这属于哪种部署模型？","o":{"A":"混合云","B":"多云","C":"私有云","D":"社区云"},"a":["B"],"e":"多云（Multi-cloud）指组织同时使用两家或以上的公有云提供商。常见动机是规避单一供应商锁定、利用各家的特色服务，或因并购而继承了不同平台。管理多云环境的难点在于工具和技能不统一——Azure Arc 就是为跨云统一治理而设计的。","r":{"A":"混合云强调的是「公有云 + 私有/本地」的组合，而不是两家公有云。","C":"私有云是单一组织独占的环境，与题干描述不符。","D":"AZ-900 官方大纲中的部署模型只有公有云、私有云、混合云和多云，不包含社区云。"},"rt":"云计算的部署模型","ru":"https://learn.microsoft.com/training/modules/describe-cloud-compute/"},{"id":"D1-011","d":"cloud-concepts","t":"云部署模型","k":"single","q":"哪个 Azure 服务允许你在 Azure 门户中统一管理和治理位于本地、其他云以及边缘的服务器和 Kubernetes 群集？","o":{"A":"Azure Arc","B":"Azure Migrate","C":"Azure VMware 解决方案","D":"Azure Site Recovery"},"a":["A"],"e":"Azure Arc 把 Azure Resource Manager 的管理平面延伸到 Azure 之外：本地服务器、其他云上的虚拟机、Kubernetes 群集、SQL Server 都可以「投射」成 Azure 资源，从而套用 Azure Policy、RBAC、标记、Azure Monitor 和 Defender for Cloud。这是多云/混合云统一治理的标准答案。","r":{"B":"Azure Migrate 用于评估和迁移本地工作负载到 Azure，是一次性的迁移工具，不做持续治理。","C":"Azure VMware 解决方案是在 Azure 中运行原生 VMware 环境，不是跨云管理工具。","D":"Azure Site Recovery 提供灾难恢复和故障转移，不是统一治理平台。"},"rt":"Azure Arc 概述","ru":"https://learn.microsoft.com/azure/azure-arc/overview"},{"id":"D1-012","d":"cloud-concepts","t":"云部署模型","k":"single","q":"某公司希望把本地 VMware 工作负载迁移到 Azure，且希望继续使用现有 VMware 工具和技能，尽量不改造应用。应该使用什么？","o":{"A":"Azure VMware 解决方案","B":"Azure 虚拟机规模集","C":"Azure Kubernetes 服务","D":"Azure Arc"},"a":["A"],"e":"Azure VMware 解决方案（AVS）在 Azure 数据中心里运行原生的 VMware vSphere/vSAN/NSX 环境，因此现有 VMware 虚拟机可以原样迁移（不需要重新平台化），团队继续用熟悉的 vCenter 管理。它是典型的「最小改动上云」路径。","r":{"B":"虚拟机规模集是 Azure 原生的 VM 弹性伸缩能力，迁移过去意味着要重建工作负载。","C":"AKS 需要把应用容器化，改造量最大。","D":"Azure Arc 是把 Azure 管理能力延伸到本地，工作负载仍留在本地，不是迁移到 Azure。"},"rt":"Azure VMware 解决方案","ru":"https://learn.microsoft.com/azure/azure-vmware/introduction"},{"id":"D1-013","d":"cloud-concepts","t":"云部署模型","k":"multi","q":"关于公有云，下列哪两项描述是正确的？（选两项）","o":{"A":"无需购买和维护硬件","B":"组织对硬件拥有完全的物理控制权","C":"资源由多个租户共享","D":"必须先投入大额资本支出才能开始使用"},"a":["A","C"],"e":"公有云的两个核心特征：①硬件由云提供商拥有和维护，客户无需资本支出；②基础设施是多租户共享的（通过虚拟化实现租户隔离）。它的优点是弹性高、起步快；代价是对底层硬件没有物理控制权。","r":{"B":"对硬件有完全物理控制权是私有云的特征，不是公有云。","D":"公有云采用即用即付的消费模型，恰恰是为了避免大额前期资本支出。"},"rt":"云计算的部署模型","ru":"https://learn.microsoft.com/training/modules/describe-cloud-compute/"},{"id":"D1-014","d":"cloud-concepts","t":"云部署模型","k":"single","q":"某金融机构因监管要求，必须对数据存放的物理硬件拥有完全控制权，并自行采购和运维设备。最合适的部署模型是？","o":{"A":"公有云","B":"私有云","C":"多云","D":"无服务器"},"a":["B"],"e":"私有云（Private cloud）是供单一组织独占使用的云环境，硬件通常由该组织自行拥有和运维（也可托管在第三方设施但仍独占）。它满足最严格的合规与数据主权要求，代价是需要资本支出、自行承担容量规划和运维。","r":{"A":"公有云是多租户共享基础设施，无法提供对物理硬件的独占控制。","C":"多云是使用多家公有云提供商，同样不提供物理硬件控制权。","D":"无服务器是一种计算模型（如 Azure Functions），不是部署模型。"},"rt":"云计算的部署模型","ru":"https://learn.microsoft.com/training/modules/describe-cloud-compute/"},{"id":"D1-015","d":"cloud-concepts","t":"云部署模型","k":"single","q":"「云爆发（cloud bursting）」最符合哪种部署模型的使用场景？","o":{"A":"公有云","B":"私有云","C":"混合云","D":"多云"},"a":["C"],"e":"云爆发指平时在本地私有环境运行，遇到流量高峰时临时把溢出的负载放到公有云，高峰过后释放。这种「本地 + 公有云协同」正是混合云的典型用例，兼顾了本地已有投资和云的弹性。","r":{"A":"纯公有云中没有需要「爆发出去」的本地容量上限。","B":"纯私有云受限于自有硬件容量，无法弹性扩展到外部。","D":"多云强调跨多个公有云提供商，不是本地容量溢出的场景。"},"rt":"云计算的部署模型","ru":"https://learn.microsoft.com/training/modules/describe-cloud-compute/"},{"id":"D1-016","d":"cloud-concepts","t":"云部署模型","k":"truefalse","q":"判断：混合云可以让组织在需要时逐步把工作负载迁移到云中，而不必一次性全部迁移。","o":{"A":"正确","B":"错误"},"a":["A"],"e":"正确。混合云的一个重要价值就是提供「渐进式迁移」路径：先把部分负载放到云上，本地与云互联共存，验证后再逐步推进。这降低了大爆炸式迁移的风险。","r":{"B":"混合云恰恰支持渐进式迁移，这是它相对「全上公有云」的主要灵活性优势。"},"rt":"云计算的部署模型","ru":"https://learn.microsoft.com/training/modules/describe-cloud-compute/"},{"id":"D1-017","d":"cloud-concepts","t":"云部署模型","k":"single","q":"关于私有云，下列哪项说法是正确的？","o":{"A":"私有云一定部署在组织自己的数据中心内","B":"私有云由单一组织独占使用，可以部署在本地或由第三方托管","C":"私有云不需要任何硬件维护","D":"私有云总是比公有云便宜"},"a":["B"],"e":"私有云的定义是「供单一组织独占使用的云环境」。它既可以建在自己的数据中心，也可以是第三方提供的专属托管环境——关键在于独占，而不是物理位置。","r":{"A":"位置不是私有云的判定标准，第三方托管的独占环境同样是私有云。","C":"私有云的硬件仍需维护，只是可能由组织自己或托管方来做。","D":"私有云通常需要前期资本支出和持续运维投入，总体成本往往高于公有云。"},"rt":"云计算的部署模型","ru":"https://learn.microsoft.com/training/modules/describe-cloud-compute/"},{"id":"D1-018","d":"cloud-concepts","t":"云部署模型","k":"single","q":"组织已有大量本地服务器，现在希望对这些服务器应用与 Azure 资源相同的标记（Tag）和 Azure Policy 策略。应采用什么方案？","o":{"A":"把服务器迁移到 Azure 虚拟机","B":"使用 Azure Arc 将服务器加入 Azure 管理","C":"在本地安装 Azure Stack HCI","D":"使用 Azure Site Recovery 复制服务器"},"a":["B"],"e":"Azure Arc 启用的服务器（Arc-enabled servers）会在 Azure 中生成一个对应的资源对象，从而可以像原生 Azure 资源一样被打标记、被 Azure Policy 评估、被 RBAC 授权、被 Azure Monitor 采集。服务器本身仍然留在本地。","r":{"A":"迁移到 Azure 虚拟机确实能纳管，但题干要求的是让「现有本地服务器」被纳管，不是迁走。","C":"Azure Stack HCI 是本地超融合基础设施平台，用于运行虚拟化工作负载，不是把已有服务器纳入 Azure 治理的方案。","D":"Site Recovery 只做灾难恢复复制，不提供标记和策略治理。"},"rt":"Azure Arc 概述","ru":"https://learn.microsoft.com/azure/azure-arc/overview"},{"id":"D1-019","d":"cloud-concepts","t":"消费模型与成本","k":"single","q":"把自建数据中心迁移到 Azure 后，公司的支出模式通常发生什么变化？","o":{"A":"从运营支出（OpEx）变为资本支出（CapEx）","B":"从资本支出（CapEx）变为运营支出（OpEx）","C":"资本支出和运营支出都会增加","D":"支出模式不会变化"},"a":["B"],"e":"自建数据中心需要预先购买服务器、存储、网络设备和机房，这些是资本支出（CapEx，一次性大额投入、逐年折旧）。上云后改为按使用量付费，成为运营支出（OpEx，持续的经营费用，通常当年即可抵扣）。这是云经济学最核心的考点。","r":{"A":"方向说反了——上云是 CapEx 转 OpEx。","C":"上云的目的之一正是消除前期资本支出。","D":"支出模式的变化是上云最显著的财务影响之一。"},"rt":"CapEx 与 OpEx","ru":"https://learn.microsoft.com/training/modules/describe-cloud-compute/"},{"id":"D1-020","d":"cloud-concepts","t":"消费模型与成本","k":"multi","q":"基于消费的定价模型（consumption-based model）有哪两个特征？（选两项）","o":{"A":"无需前期购买硬件的资本支出","B":"按实际使用的资源量付费","C":"必须签订三年期的固定合同","D":"必须一次性预付全年费用"},"a":["A","B"],"e":"消费模型（也叫即用即付，pay-as-you-go）的两大特征：没有前期资本支出；只为实际消耗的资源付费，不用时停止计费。它带来的好处是「为增长付费而不是为容量付费」——不必按峰值采购硬件。","r":{"C":"固定期限合同是预留实例/节省计划等折扣方案的特征，不是消费模型本身的要求。","D":"消费模型是用多少付多少、按周期结算，不需要一次性预付全年。"},"rt":"基于消费的模型","ru":"https://learn.microsoft.com/training/modules/describe-cloud-compute/"},{"id":"D1-021","d":"cloud-concepts","t":"消费模型与成本","k":"single","q":"下列哪一项属于资本支出（CapEx）？","o":{"A":"每月支付的 Azure 虚拟机使用费","B":"购买本地服务器和存储阵列","C":"Azure 存储的出站数据传输费","D":"Microsoft 365 订阅的月费"},"a":["B"],"e":"CapEx 是为获取长期资产而发生的一次性大额支出：服务器、存储阵列、机房、网络设备、软件永久授权等，需要在使用年限内折旧。而按月/按量支付的云服务费属于 OpEx。","r":{"A":"按使用量按月结算的云费用是典型的 OpEx。","C":"数据传输费按实际流量计费，属于 OpEx。","D":"订阅月费是持续性的经营费用，属于 OpEx。"},"rt":"CapEx 与 OpEx","ru":"https://learn.microsoft.com/training/modules/describe-cloud-compute/"},{"id":"D1-022","d":"cloud-concepts","t":"消费模型与成本","k":"single","q":"使用云的消费模型时，下列哪项描述最准确地体现了它的成本优势？","o":{"A":"云总是比本地便宜","B":"可以按峰值需求采购容量并长期持有","C":"可以在需求下降时缩减资源，从而只为真正使用的容量付费","D":"可以完全消除所有 IT 支出"},"a":["C"],"e":"消费模型的成本优势来自「弹性」：需求上升时扩容、下降时缩容，付费随之变化。本地数据中心必须按峰值采购，平时大量容量闲置——这部分浪费正是云要消除的。","r":{"A":"云不一定总更便宜，长期满载的稳定负载有时本地更划算；这是常见的过度简化。","B":"按峰值长期持有容量恰恰是本地数据中心的缺点，不是云的优势。","D":"上云只是改变支出结构，IT 支出不可能被消除。"},"rt":"基于消费的模型","ru":"https://learn.microsoft.com/training/modules/describe-cloud-compute/"},{"id":"D1-023","d":"cloud-concepts","t":"消费模型与成本","k":"truefalse","q":"判断：在 Azure 中，如果停止（解除分配）一台虚拟机，该虚拟机的计算费用会停止产生，但其托管磁盘的存储费用仍会继续产生。","o":{"A":"正确","B":"错误"},"a":["A"],"e":"正确。停止并解除分配（Stop-Deallocated）虚拟机后不再计算计算资源费用，但附加的托管磁盘、预留的公共 IP 等资源依然占用存储/资源，仍会计费。要彻底停止计费必须删除这些资源。这是考试和实务中都很常见的陷阱。","r":{"B":"误区在于以为「关机 = 完全不花钱」；磁盘等持久化资源会继续计费。"},"rt":"Azure 成本管理概述","ru":"https://learn.microsoft.com/azure/cost-management-billing/costs/overview-cost-management"},{"id":"D1-024","d":"cloud-concepts","t":"消费模型与成本","k":"single","q":"云计算的「即用即付」模型如何帮助企业处理无法预测的业务增长？","o":{"A":"允许企业提前锁定固定价格","B":"允许企业随时增加资源，只为新增的用量付费，无需重新采购硬件","C":"保证企业的月度账单固定不变","D":"免除企业的所有网络费用"},"a":["B"],"e":"面对无法预测的增长，本地环境需要提前数周甚至数月采购和上架硬件；云中只需几分钟就能扩容，且只为新增用量付费。这就是云的「敏捷性 + 弹性」带来的业务价值。","r":{"A":"锁定固定价格是预留实例/节省计划的特征，与即用即付相反。","C":"即用即付的账单随用量波动，并不固定。","D":"网络出站流量等仍会计费，不会被免除。"},"rt":"基于消费的模型","ru":"https://learn.microsoft.com/training/modules/describe-cloud-compute/"},{"id":"D1-025","d":"cloud-concepts","t":"消费模型与成本","k":"single","q":"下列哪项最能说明云计算带来的「敏捷性（Agility）」好处？","o":{"A":"自动为数据创建三个副本","B":"几分钟内即可部署和取消部署资源以响应业务变化","C":"保证 99.99% 的可用性 SLA","D":"通过 Azure Policy 强制资源合规"},"a":["B"],"e":"敏捷性指快速响应变化的能力：新想法可以在几分钟内获得所需的计算、存储和网络资源，验证失败后立即释放。这让实验成本极低，是云相对本地采购周期最显著的优势。","r":{"A":"自动创建多个副本描述的是可靠性/冗余，不是敏捷性。","C":"可用性 SLA 属于高可用性范畴。","D":"强制合规属于治理与安全范畴。"},"rt":"云的优势","ru":"https://learn.microsoft.com/training/modules/describe-cloud-compute/"},{"id":"D1-026","d":"cloud-concepts","t":"云的优势","k":"single","q":"把一台虚拟机从 2 核 8GB 内存升级为 8 核 32GB 内存，这属于哪种缩放方式？","o":{"A":"水平缩放（横向扩展）","B":"垂直缩放（纵向扩展）","C":"地理复制","D":"负载均衡"},"a":["B"],"e":"垂直缩放（Vertical scaling / scale up）是给同一个实例增加 CPU、内存等资源，让单个实例变得更强。水平缩放（Horizontal scaling / scale out）则是增加实例数量。考试中常用「换更大的 VM 型号」来考垂直缩放。","r":{"A":"水平缩放是增加/减少实例数量，而不是改变单个实例的规格。","C":"地理复制是把数据复制到其他区域，属于冗余/灾备范畴。","D":"负载均衡是把流量分发到多个实例，是水平缩放的配套能力。"},"rt":"云的优势：缩放性","ru":"https://learn.microsoft.com/training/modules/describe-benefits-use-cloud-services/"},{"id":"D1-027","d":"cloud-concepts","t":"云的优势","k":"single","q":"在促销期间，应用自动从 3 个实例增加到 20 个实例，促销结束后自动缩回 3 个。这体现了云的哪个特性？","o":{"A":"高可用性","B":"弹性（Elasticity）","C":"灾难恢复","D":"治理"},"a":["B"],"e":"弹性指资源随需求自动增减的能力（自动缩放）。它建立在水平缩放之上，并直接带来成本优势——高峰时有足够容量，低谷时不为闲置资源付费。","r":{"A":"高可用性关注的是「服务保持可用的时间比例」，不是随需求增减容量。","C":"灾难恢复关注区域级故障后的业务恢复，不是日常的负载波动。","D":"治理关注的是合规与策略控制，与自动伸缩无关。"},"rt":"云的优势：弹性","ru":"https://learn.microsoft.com/training/modules/describe-benefits-use-cloud-services/"},{"id":"D1-028","d":"cloud-concepts","t":"云的优势","k":"single","q":"云的「可靠性（Reliability）」主要通过什么方式实现？","o":{"A":"通过分散式的全球基础设施，在某部分发生故障时仍能继续运行并自动恢复","B":"通过对所有数据加密","C":"通过限制用户访问权限","D":"通过降低资源价格"},"a":["A"],"e":"可靠性是系统从故障中恢复并继续运行的能力。云的分散式设计（多区域、多可用性区域、多副本）使得单点故障不会导致整体服务不可用，并支持自动故障转移。可靠性是 Azure 架构良好框架（Well-Architected Framework）的支柱之一。","r":{"B":"加密属于安全范畴，保护的是机密性，不是故障恢复能力。","C":"限制访问权限属于安全与治理，不是可靠性。","D":"价格与可靠性无关。"},"rt":"云的优势：可靠性","ru":"https://learn.microsoft.com/training/modules/describe-benefits-use-cloud-services/"},{"id":"D1-029","d":"cloud-concepts","t":"云的优势","k":"multi","q":"云的「可预测性（Predictability）」包含哪两个方面？（选两项）","o":{"A":"性能可预测性","B":"成本可预测性","C":"地理位置可预测性","D":"硬件型号可预测性"},"a":["A","B"],"e":"可预测性分两类：①性能可预测性——通过自动缩放、负载均衡、高可用设计，保证用户体验稳定；②成本可预测性——通过定价计算器、TCO 计算器、Cost Management 和预算警报，预测和跟踪花费。","r":{"C":"资源的地理位置由你选择的区域决定，不属于官方定义的可预测性范畴。","D":"云屏蔽了底层硬件细节，硬件型号不是可预测性的组成部分。"},"rt":"云的优势：可预测性","ru":"https://learn.microsoft.com/training/modules/describe-benefits-use-cloud-services/"},{"id":"D1-030","d":"cloud-concepts","t":"云的优势","k":"single","q":"「云中的管理（management in the cloud）」指的是下列哪一项？","o":{"A":"自动缩放资源以满足需求","B":"通过 Azure 门户、CLI、PowerShell 和 ARM 模板来管理云资源","C":"自动部署资源的模板化能力","D":"在资源不正常时自动替换资源"},"a":["B"],"e":"官方把管理性分为两类：①「云的管理（management of the cloud）」——云替你做的事，如自动缩放、按模板部署、自动替换失败资源、监控与警报；②「云中的管理（management in the cloud）」——你如何管理云环境，即 Azure 门户、Azure CLI、Azure PowerShell、REST API 和 ARM/Bicep 模板。","r":{"A":"自动缩放属于「云的管理」。","C":"模板化自动部署属于「云的管理」。","D":"自动替换失败资源属于「云的管理」。"},"rt":"云的优势：管理性","ru":"https://learn.microsoft.com/training/modules/describe-benefits-use-cloud-services/"},{"id":"D1-031","d":"cloud-concepts","t":"云的优势","k":"single","q":"服务级别协议（SLA）中的 99.9% 可用性，大约对应每月多长的允许停机时间？","o":{"A":"约 43 分钟","B":"约 4.5 分钟","C":"约 8.8 小时","D":"约 22 小时"},"a":["A"],"e":"99.9%（三个九）每月允许的停机时间约为 43.2 分钟；99.99%（四个九）约 4.4 分钟；99%（两个九）约 7.3 小时。记住这个换算关系有助于理解为什么提高一个「九」的成本会大幅上升。","r":{"B":"约 4.5 分钟对应的是 99.99%，不是 99.9%。","C":"约 8.8 小时接近 99%（约 7.3 小时）的量级，远低于 99.9%。","D":"约 22 小时对应大约 97% 的可用性，远低于题目所问。"},"rt":"Azure 服务级别协议","ru":"https://learn.microsoft.com/azure/reliability/reliability-guidance-overview"},{"id":"D1-032","d":"cloud-concepts","t":"云的优势","k":"single","q":"把应用部署到多个可用性区域，主要是为了获得什么好处？","o":{"A":"降低成本","B":"提高高可用性，使单个数据中心故障不影响服务","C":"简化代码","D":"提高数据加密强度"},"a":["B"],"e":"可用性区域是同一 Azure 区域内物理分离的数据中心（各自独立供电、制冷、网络）。把实例分布到多个区域可以让单个数据中心级别的故障不中断服务，因此是提升高可用性的标准做法，通常也是获得更高 SLA 的前提。","r":{"A":"跨区域部署需要更多实例和跨区域流量，成本通常上升而不是下降。","C":"跨区域部署反而对应用架构提出更高要求（如无状态化），不会简化代码。","D":"加密强度由加密算法和密钥管理决定，与部署位置无关。"},"rt":"可用性区域概述","ru":"https://learn.microsoft.com/azure/reliability/availability-zones-overview"},{"id":"D1-033","d":"cloud-concepts","t":"云的优势","k":"single","q":"下列哪一项属于云在「治理（Governance）」方面的优势？","o":{"A":"按需增减虚拟机数量","B":"使用模板和策略确保所有部署的资源都符合公司标准和法规要求","C":"在多个区域间复制数据","D":"按使用量付费"},"a":["B"],"e":"治理优势体现在：用基于模板的部署（ARM/Bicep）保证一致性，用 Azure Policy 审核和强制资源合规（如必须打标记、只能部署在指定区域），用 Advisor 和 Defender for Cloud 主动发现偏差。这让合规从「事后人工检查」变成「事前自动强制」。","r":{"A":"按需增减实例属于缩放性/弹性。","C":"跨区域复制数据属于可靠性/灾难恢复。","D":"按使用量付费属于消费模型/成本优势。"},"rt":"云的优势：治理","ru":"https://learn.microsoft.com/training/modules/describe-benefits-use-cloud-services/"},{"id":"D1-034","d":"cloud-concepts","t":"云的优势","k":"multi","q":"下列哪两项是云在安全性方面为客户带来的优势？（选两项）","o":{"A":"客户可以选择由云提供商负责更多安全层（例如选择 PaaS 而非 IaaS）","B":"云提供商承担客户数据的分类与访问授权责任","C":"云提供商提供的工具和基线可以帮助客户快速达到合规要求","D":"使用云后客户不再需要考虑安全"},"a":["A","C"],"e":"云的安全优势有两层：①可以通过选择更高层的服务（PaaS/SaaS）把更多安全职责交给提供商；②提供商提供成熟的安全工具（Defender for Cloud、Azure Policy、合规基线、服务信任门户文档）帮助客户更快达到合规。但数据分类和授权始终是客户责任。","r":{"B":"数据的分类与访问授权永远是客户的责任，云提供商不承担。","D":"这是典型的错误观念；共享责任模型下客户依然有明确的安全责任。"},"rt":"云的优势：安全性","ru":"https://learn.microsoft.com/training/modules/describe-benefits-use-cloud-services/"},{"id":"D1-035","d":"cloud-concepts","t":"云的优势","k":"single","q":"水平缩放（scale out）指的是什么？","o":{"A":"为现有虚拟机增加 CPU 和内存","B":"增加运行同一工作负载的实例数量","C":"把工作负载迁移到另一个区域","D":"增加磁盘的容量"},"a":["B"],"e":"水平缩放是增加（scale out）或减少（scale in）实例数量。它的优势是几乎没有上限、可以做到零停机、并且天然配合高可用；缺点是应用需要支持无状态和负载均衡。虚拟机规模集（VMSS）就是实现水平缩放的服务。","r":{"A":"为现有实例增加 CPU 和内存是垂直缩放（scale up）。","C":"跨区域迁移属于灾备或数据驻留策略，不是缩放。","D":"增加磁盘容量是存储层的垂直扩展，不是题目所问的实例数量扩展。"},"rt":"云的优势：缩放性","ru":"https://learn.microsoft.com/training/modules/describe-benefits-use-cloud-services/"},{"id":"D1-036","d":"cloud-concepts","t":"云的优势","k":"single","q":"关于「高可用性」和「灾难恢复」的区别，下列说法正确的是？","o":{"A":"两者是同一个概念的不同叫法","B":"高可用性关注在区域内应对组件故障保持服务运行；灾难恢复关注整个区域级灾难后恢复业务","C":"高可用性只适用于存储，灾难恢复只适用于计算","D":"灾难恢复不需要任何预先规划"},"a":["B"],"e":"高可用性（HA）解决的是「日常的局部故障」——某台主机、某个机架、某个数据中心（可用性区域）挂了服务照常；灾难恢复（DR）解决的是「整个区域不可用」的极端场景，依靠跨区域复制、区域对和故障转移计划。二者的衡量指标不同：HA 看可用性百分比，DR 看 RTO/RPO。","r":{"A":"两者目标、机制和衡量指标都不同，不能混为一谈。","C":"HA 和 DR 都同时涉及计算、存储、网络和数据。","D":"灾难恢复恰恰最需要预先规划（复制策略、RTO/RPO 目标、演练）。"},"rt":"可靠性与灾难恢复","ru":"https://learn.microsoft.com/azure/reliability/overview"},{"id":"D1-037","d":"cloud-concepts","t":"云的优势","k":"truefalse","q":"判断：自动缩放属于「云的管理（management of the cloud）」能力。","o":{"A":"正确","B":"错误"},"a":["A"],"e":"正确。「云的管理」是指云平台替你完成的管理工作，包括自动缩放、基于模板的自动部署、在资源不正常时自动替换、以及监控与警报。与之相对的「云中的管理」是你使用门户、CLI、PowerShell、API 和模板来操作云。","r":{"B":"自动缩放由平台自动执行，属于「云的管理」，而不是「云中的管理」。"},"rt":"云的优势：管理性","ru":"https://learn.microsoft.com/training/modules/describe-benefits-use-cloud-services/"},{"id":"D1-038","d":"cloud-concepts","t":"云服务类型 IaaS/PaaS/SaaS","k":"single","q":"哪种云服务类型给予客户对基础设施的最大控制权，同时也要求客户承担最多的管理责任？","o":{"A":"IaaS","B":"PaaS","C":"SaaS","D":"FaaS"},"a":["A"],"e":"IaaS（基础结构即服务）把硬件租给你：你拿到虚拟机、虚拟网络和磁盘，操作系统及以上全部自己管。控制权最大，责任也最重。记忆口诀：IaaS「租硬件」，PaaS「租平台」，SaaS「租软件」。","r":{"B":"PaaS 由提供商管理操作系统和运行时，客户控制权较小。","C":"SaaS 客户控制权最小，只能配置应用的使用方式。","D":"FaaS（函数即服务）是 PaaS 的一个细分形态，控制权更小而非更大。"},"rt":"云服务类型","ru":"https://learn.microsoft.com/training/modules/describe-cloud-service-types/"},{"id":"D1-039","d":"cloud-concepts","t":"云服务类型 IaaS/PaaS/SaaS","k":"single","q":"开发团队希望部署 Web 应用，但不想管理底层操作系统、补丁和服务器。应该选择哪种云服务类型？","o":{"A":"IaaS","B":"PaaS","C":"SaaS","D":"私有云"},"a":["B"],"e":"PaaS（平台即服务）为开发者提供托管的应用运行环境——操作系统、运行时、补丁、负载均衡都由平台负责，开发者只管代码和数据。Azure App Service、Azure SQL 数据库、Azure Functions 都是 PaaS 的典型代表。","r":{"A":"IaaS 中仍需自行管理操作系统和补丁，与需求相反。","C":"SaaS 提供的是现成的软件（如 Microsoft 365），不能用来部署自研应用。","D":"私有云是部署模型，不是回答「谁管操作系统」的服务类型。"},"rt":"云服务类型：PaaS","ru":"https://learn.microsoft.com/training/modules/describe-cloud-service-types/"},{"id":"D1-040","d":"cloud-concepts","t":"云服务类型 IaaS/PaaS/SaaS","k":"single","q":"Microsoft 365 和 Dynamics 365 属于哪种云服务类型？","o":{"A":"IaaS","B":"PaaS","C":"SaaS","D":"混合云"},"a":["C"],"e":"SaaS（软件即服务）是直接按订阅使用的完整软件产品，提供商负责从硬件到应用的一切，客户只负责自己的数据、设备和账户。Microsoft 365、Dynamics 365、Outlook.com 都是 SaaS。","r":{"A":"IaaS 提供的是虚拟机等基础设施，不是成品软件。","B":"PaaS 提供的是开发和运行应用的平台，客户仍需自行开发应用。","D":"混合云是部署模型，不是服务类型。"},"rt":"云服务类型：SaaS","ru":"https://learn.microsoft.com/training/modules/describe-cloud-service-types/"},{"id":"D1-041","d":"cloud-concepts","t":"云服务类型 IaaS/PaaS/SaaS","k":"single","q":"公司需要把本地虚拟机「原样搬迁（lift and shift）」到云中，尽量不修改应用。最合适的服务类型是？","o":{"A":"IaaS","B":"PaaS","C":"SaaS","D":"无服务器"},"a":["A"],"e":"lift and shift（提升并转移）指把现有工作负载原封不动搬到云上。IaaS 提供与本地虚拟机最接近的环境，因此改造量最小、迁移最快。代价是上云后仍要自己管操作系统，享受不到 PaaS 的免运维红利。","r":{"B":"改用 PaaS 通常需要重构应用（重新平台化），不符合「不修改应用」的要求。","C":"SaaS 意味着用现成软件替换自研应用，改动最大。","D":"无服务器要求把应用拆成事件驱动的函数，改造量极大。"},"rt":"云服务类型：IaaS 用例","ru":"https://learn.microsoft.com/training/modules/describe-cloud-service-types/"},{"id":"D1-042","d":"cloud-concepts","t":"云服务类型 IaaS/PaaS/SaaS","k":"multi","q":"在 PaaS 场景下，下列哪两项由客户负责？（选两项）","o":{"A":"操作系统补丁","B":"应用程序中存储的数据","C":"物理网络","D":"用户账户与访问权限"},"a":["B","D"],"e":"PaaS 中 Microsoft 负责物理设施、网络、虚拟化和操作系统；客户负责数据、账户与标识、以及自己的设备。应用程序和标识与目录基础结构属于共担项。数据和身份永远是客户责任——这是贯穿整个共享责任模型的主线。","r":{"A":"PaaS 中操作系统由 Microsoft 维护，这正是 PaaS 相对 IaaS 的主要价值。","C":"物理网络永远由 Microsoft 负责。"},"rt":"共享责任模型","ru":"https://learn.microsoft.com/azure/security/fundamentals/shared-responsibility"},{"id":"D1-043","d":"cloud-concepts","t":"云服务类型 IaaS/PaaS/SaaS","k":"single","q":"无服务器（Serverless）计算最准确的描述是？","o":{"A":"运行代码时不涉及任何服务器","B":"开发者无需预配或管理服务器，平台按事件自动分配资源并按执行计费","C":"只能运行静态网站","D":"必须先购买预留实例"},"a":["B"],"e":"无服务器并不是「没有服务器」，而是「服务器由平台管理，开发者看不见也不需要管」。平台按请求或事件自动分配资源、自动伸缩（可缩到零），并按实际执行时间/次数计费。Azure Functions 和 Azure Logic Apps 是代表服务。","r":{"A":"字面理解错误——底层仍然运行在服务器上，只是对开发者透明。","C":"无服务器可以运行各种事件驱动的业务逻辑，不限于静态网站。","D":"无服务器通常按执行量计费，不要求购买预留实例。"},"rt":"Azure Functions 概述","ru":"https://learn.microsoft.com/azure/azure-functions/functions-overview"},{"id":"D1-044","d":"cloud-concepts","t":"云服务类型 IaaS/PaaS/SaaS","k":"single","q":"下列哪个 Azure 服务属于 IaaS？","o":{"A":"Azure 虚拟机","B":"Azure App Service","C":"Azure SQL 数据库","D":"Microsoft 365"},"a":["A"],"e":"Azure 虚拟机是最典型的 IaaS：你获得一台虚拟服务器，自己选择操作系统镜像、自己安装软件、自己打补丁。App Service 和 Azure SQL 数据库是 PaaS，Microsoft 365 是 SaaS。","r":{"B":"App Service 是托管的 Web 应用平台，属于 PaaS。","C":"Azure SQL 数据库是托管数据库服务，属于 PaaS。","D":"Microsoft 365 是成品办公软件套件，属于 SaaS。"},"rt":"云服务类型","ru":"https://learn.microsoft.com/training/modules/describe-cloud-service-types/"},{"id":"D1-045","d":"cloud-concepts","t":"云服务类型 IaaS/PaaS/SaaS","k":"single","q":"某初创公司希望以最低的运维投入快速上线一个电子邮件与协作系统。最合适的选择是？","o":{"A":"在 Azure 虚拟机上自建 Exchange Server","B":"使用 Azure App Service 自研邮件系统","C":"订阅 Microsoft 365","D":"在本地部署私有云"},"a":["C"],"e":"需求是「现成能力 + 最低运维」，这正是 SaaS 的定位。订阅 Microsoft 365 后无需部署、无需打补丁、无需容量规划，按用户数付费即可使用邮件、文档协作等完整能力。","r":{"A":"在 VM 上自建 Exchange 是 IaaS 路线，运维负担最重。","B":"自研邮件系统开发成本极高，完全不符合「最低投入快速上线」。","D":"自建私有云需要采购硬件和长周期建设，与快速上线矛盾。"},"rt":"云服务类型：SaaS 用例","ru":"https://learn.microsoft.com/training/modules/describe-cloud-service-types/"},{"id":"D1-046","d":"cloud-concepts","t":"云服务类型 IaaS/PaaS/SaaS","k":"single","q":"下列关于 IaaS、PaaS、SaaS 管理责任的排序，哪一项是正确的（从客户管理最多到最少）？","o":{"A":"SaaS → PaaS → IaaS","B":"IaaS → PaaS → SaaS","C":"PaaS → IaaS → SaaS","D":"三者的客户管理责任相同"},"a":["B"],"e":"客户管理责任从多到少依次是 IaaS → PaaS → SaaS；提供商责任则相反。考试中经常用「谁管得最多/最少」「控制权最大/最小」的说法来考这个排序，记住这条单调的阶梯即可。","r":{"A":"顺序完全颠倒了，SaaS 客户管理责任最少。","C":"PaaS 的客户责任小于 IaaS，不应排在最前。","D":"三种服务类型的责任划分明显不同，这是整个模型的基础。"},"rt":"共享责任模型","ru":"https://learn.microsoft.com/azure/security/fundamentals/shared-responsibility"},{"id":"D1-047","d":"cloud-concepts","t":"云服务类型 IaaS/PaaS/SaaS","k":"single","q":"某公司要运行一个只在每天凌晨执行几分钟的数据清理任务，希望不运行时完全不产生计算费用。最合适的方案是？","o":{"A":"常开的 Azure 虚拟机","B":"Azure Functions（消耗计划）","C":"Azure 虚拟机规模集","D":"Azure VMware 解决方案"},"a":["B"],"e":"Azure Functions 的消耗（Consumption）计划是无服务器模型：由计时器触发，只在执行期间计费，空闲时可缩放到零实例，费用为零。这正是「短时、间歇性任务」的最佳成本方案。","r":{"A":"常开虚拟机 24 小时计费，绝大部分时间在空转，成本最高。","C":"规模集即使缩到最小实例数也仍在运行并计费。","D":"Azure VMware 解决方案是专用的 VMware 私有云集群，成本高且与场景完全不符。"},"rt":"Azure Functions 概述","ru":"https://learn.microsoft.com/azure/azure-functions/functions-overview"},{"id":"D2-001","d":"architecture-services","t":"核心架构：区域与可用性区域","k":"single","q":"Azure 区域（Region）的定义是什么？","o":{"A":"一个单独的物理数据中心","B":"一组通过低延迟网络互联的数据中心所构成的地理区域","C":"一个 Azure 订阅的计费边界","D":"一组虚拟机的逻辑集合"},"a":["B"],"e":"Azure 区域是一个地理区域内由一个或多个数据中心组成、通过低延迟网络互联的集合。部署资源时选择区域，主要考虑三点：①靠近用户以降低延迟 ②数据驻留/合规要求 ③该区域是否提供所需服务（并非所有服务在所有区域可用）。","r":{"A":"单个数据中心只是区域的组成部分，一个区域通常包含多个数据中心。","C":"计费边界是订阅（Subscription），不是区域。","D":"虚拟机的逻辑集合是资源组或可用性集，不是区域。"},"rt":"Azure 区域概述","ru":"https://learn.microsoft.com/azure/reliability/regions-overview"},{"id":"D2-002","d":"architecture-services","t":"核心架构：区域与可用性区域","k":"single","q":"关于 Azure 可用性区域（Availability Zone），下列说法正确的是？","o":{"A":"可用性区域是位于不同 Azure 区域的数据中心","B":"同一区域内物理隔离的数据中心，各自拥有独立的供电、制冷和网络","C":"可用性区域之间的距离至少 300 英里","D":"每个 Azure 区域都提供可用性区域"},"a":["B"],"e":"可用性区域是同一个 Azure 区域内物理分离的位置，每个区域拥有独立的电源、冷却和网络。启用可用性区域的区域至少有三个区域。把实例分布到多个可用性区域可以抵御数据中心级别的故障，是区域内高可用的标准做法。","r":{"A":"跨 Azure 区域的概念是「区域对」和多区域部署，不是可用性区域。","C":"300 英里是「区域对」之间的最小距离要求，不是可用性区域之间。可用性区域在同一区域内，距离近到能保证低延迟同步复制。","D":"并非所有 Azure 区域都支持可用性区域，部署前需要确认目标区域是否启用。"},"rt":"可用性区域概述","ru":"https://learn.microsoft.com/azure/reliability/availability-zones-overview"},{"id":"D2-003","d":"architecture-services","t":"核心架构：区域与可用性区域","k":"single","q":"下列哪项是「区域对（Region Pair）」的特征？","o":{"A":"两个区域位于同一个数据中心","B":"配对的区域通常相距至少 300 英里，且计划内更新一次只在其中一个区域推出","C":"区域对之间的数据会自动同步所有资源","D":"区域对内的两个区域必须属于不同的地理位置（Geography）"},"a":["B"],"e":"区域对是同一地理位置内的两个区域，通常相距 300 英里以上，用于降低自然灾害、电力故障等同时影响两地的风险。Azure 的计划内平台更新一次只在配对中的一个区域推出；发生大范围中断时，配对区域中的一个会被优先恢复。","r":{"A":"区域对是两个相距很远的独立区域，绝不在同一数据中心。","C":"区域对本身不自动复制资源——只有选择了异地冗余存储（GRS/GZRS）等跨区域复制功能，数据才会复制到配对区域。","D":"恰恰相反，区域对通常位于同一地理位置内以满足数据驻留要求（巴西南部因地理位置内无其他区域而与美国中南部配对，属于著名例外）。"},"rt":"跨区域复制与区域对","ru":"https://learn.microsoft.com/azure/reliability/cross-region-replication-azure"},{"id":"D2-004","d":"architecture-services","t":"核心架构：区域与可用性区域","k":"multi","q":"下列哪两个属于 Azure 的主权区域（Sovereign Region）？（选两项）","o":{"A":"Azure 政府版（Azure Government）","B":"由世纪互联运营的 Azure 中国区","C":"Azure 美国东部","D":"Azure 西欧"},"a":["A","B"],"e":"主权区域是与全球 Azure 实例物理和逻辑隔离的独立云：Azure 政府版（面向美国联邦、州、地方政府及其合作伙伴）和由世纪互联运营的 Azure 中国区（满足中国法规要求）。它们使用独立的门户地址、独立的标识系统，服务可用性也与全球 Azure 不同。","r":{"C":"美国东部是全球 Azure 的普通公有区域。","D":"西欧是全球 Azure 的普通公有区域。"},"rt":"Azure 区域概述","ru":"https://learn.microsoft.com/azure/reliability/regions-overview"},{"id":"D2-005","d":"architecture-services","t":"核心架构：区域与可用性区域","k":"single","q":"选择部署区域时，下列哪项通常不是主要考虑因素？","o":{"A":"与最终用户的距离（延迟）","B":"数据驻留和合规要求","C":"该区域是否提供所需的服务","D":"该区域的数据中心建筑面积"},"a":["D"],"e":"选择区域的三大标准是：合规与数据驻留、服务可用性、以及与用户的距离（延迟），此外不同区域的价格也可能不同。数据中心的物理规模是 Microsoft 的运营细节，客户既看不到也不需要关心。","r":{"A":"延迟直接影响用户体验，是核心考虑因素。","B":"某些法规要求数据必须保存在特定国家/地区，这是首要约束。","C":"新服务通常先在部分区域上线，必须确认目标区域支持。"},"rt":"Azure 区域概述","ru":"https://learn.microsoft.com/azure/reliability/regions-overview"},{"id":"D2-006","d":"architecture-services","t":"核心架构：区域与可用性区域","k":"single","q":"某应用必须在单个数据中心发生整体故障时仍然可用，但所有组件需保持在同一区域内以满足数据驻留要求。应采用什么方案？","o":{"A":"部署到区域对中的两个区域","B":"将实例分布到该区域的多个可用性区域","C":"使用本地冗余存储（LRS）","D":"使用 Azure Traffic Manager 做全球路由"},"a":["B"],"e":"要求是「抵御数据中心级故障」+「不出区域」，这正是可用性区域的定位：同区域内物理隔离的多个数据中心，既满足数据驻留，又能在单个数据中心失效时继续提供服务。","r":{"A":"跨区域部署会把数据放到另一个区域，可能违反数据驻留要求。","C":"LRS 在单个数据中心内保存三个副本，该数据中心整体故障时数据不可用。","D":"Traffic Manager 只是 DNS 级流量路由，本身不提供跨数据中心的冗余部署。"},"rt":"可用性区域概述","ru":"https://learn.microsoft.com/azure/reliability/availability-zones-overview"},{"id":"D2-007","d":"architecture-services","t":"核心架构：区域与可用性区域","k":"truefalse","q":"判断：所有 Azure 服务在所有 Azure 区域中都可用。","o":{"A":"正确","B":"错误"},"a":["B"],"e":"错误。Azure 服务的区域可用性各不相同：新服务通常先在少数区域预览，逐步扩展；部分服务是全球性的（如 Microsoft Entra ID、Azure DNS）不绑定区域。设计架构前必须查阅「按区域提供的产品」页面确认。","r":{"A":"这是常见误区。服务可用性因区域而异，必须事先确认。"},"rt":"Azure 区域概述","ru":"https://learn.microsoft.com/azure/reliability/regions-overview"},{"id":"D2-008","d":"architecture-services","t":"核心架构：资源组织层级","k":"single","q":"Azure 资源组织层级从上到下的正确顺序是？","o":{"A":"管理组 → 订阅 → 资源组 → 资源","B":"订阅 → 管理组 → 资源组 → 资源","C":"资源组 → 订阅 → 管理组 → 资源","D":"订阅 → 资源组 → 管理组 → 资源"},"a":["A"],"e":"层级自上而下是：管理组（Management group）→ 订阅（Subscription）→ 资源组（Resource group）→ 资源（Resource）。上层施加的 Azure Policy 和 RBAC 权限会向下继承，这是整个 Azure 治理体系的基础。","r":{"B":"管理组在订阅之上，用于统一管理多个订阅。","C":"资源组是最底层的容器，不可能在订阅之上。","D":"管理组不可能位于资源组之下。"},"rt":"Azure Resource Manager 概述","ru":"https://learn.microsoft.com/azure/azure-resource-manager/management/overview"},{"id":"D2-009","d":"architecture-services","t":"核心架构：资源组织层级","k":"multi","q":"关于 Azure 资源组，下列哪两项说法是正确的？（选两项）","o":{"A":"一个资源只能属于一个资源组","B":"资源组可以嵌套在另一个资源组中","C":"同一个资源组中的资源可以位于不同的区域","D":"删除资源组不会删除其中的资源"},"a":["A","C"],"e":"资源组是资源的逻辑容器：①每个资源有且只有一个资源组归属（可以移动到别的资源组，但不能同时属于两个）；②资源组本身有一个位置（用于存放元数据），但其中的资源可以分布在任意区域。常见做法是把同生命周期的资源放在一个资源组里统一部署和删除。","r":{"B":"资源组不能嵌套，这是明确的限制。要做多层分组请使用管理组和订阅。","D":"删除资源组会删除其中的所有资源，这是考试和实务中都必须牢记的高危操作。"},"rt":"资源组管理","ru":"https://learn.microsoft.com/azure/azure-resource-manager/management/overview"},{"id":"D2-010","d":"architecture-services","t":"核心架构：资源组织层级","k":"single","q":"Azure 订阅（Subscription）主要提供什么边界？","o":{"A":"仅提供网络边界","B":"计费边界和访问控制边界","C":"物理数据中心边界","D":"身份验证边界"},"a":["B"],"e":"订阅提供两类边界：①计费边界——每个订阅生成独立的账单和成本报告，常用于按部门/项目分摊成本；②访问控制边界——可以在订阅级别授予 RBAC 角色和应用策略，实现不同部门的隔离管理。订阅上还有服务配额和限制。","r":{"A":"网络边界由虚拟网络（VNet）提供，不是订阅。","C":"订阅是逻辑概念，与物理数据中心无关。","D":"身份验证边界是 Microsoft Entra 租户（Tenant），一个租户可以包含多个订阅。"},"rt":"Azure 订阅","ru":"https://learn.microsoft.com/azure/cost-management-billing/manage/create-subscription"},{"id":"D2-011","d":"architecture-services","t":"核心架构：资源组织层级","k":"single","q":"某企业有 30 个 Azure 订阅，需要对所有订阅统一强制执行「只能在指定区域部署资源」的策略。最有效的做法是？","o":{"A":"在每个订阅上分别创建 Azure Policy 分配","B":"创建管理组，把所有订阅放入，在管理组级别分配策略","C":"在每个资源组上分配策略","D":"为每个订阅创建单独的 Entra 租户"},"a":["B"],"e":"管理组的存在意义就是「在订阅之上统一治理」。在管理组级别分配的 Azure Policy 和 RBAC 会被其下所有订阅、资源组和资源继承，30 个订阅只需配置一次。管理组层级最多可嵌套 6 层（不含根管理组）。","r":{"A":"配置 30 次既费时又容易遗漏，后续变更也难以同步，不是最有效的做法。","C":"资源组数量远多于订阅，工作量更大，且新建资源组会漏掉策略。","D":"拆分租户会带来身份割裂和巨大的管理复杂度，完全不解决策略统一的问题。"},"rt":"管理组概述","ru":"https://learn.microsoft.com/azure/governance/management-groups/overview"},{"id":"D2-012","d":"architecture-services","t":"核心架构：资源组织层级","k":"single","q":"关于管理组，下列说法正确的是？","o":{"A":"管理组只能包含订阅，不能包含其他管理组","B":"管理组可以包含订阅，也可以包含其他管理组，形成多层结构","C":"一个订阅可以同时属于多个管理组","D":"管理组会自动删除其下的订阅"},"a":["B"],"e":"管理组可以嵌套（订阅之上最多 6 层），从而按业务部门、环境（生产/测试）或地域构建治理树。每个目录有一个根管理组，所有其他管理组和订阅都在其下。一个订阅只能属于一个管理组。","r":{"A":"管理组支持嵌套，这正是它能表达复杂组织结构的原因。","C":"与资源只能属于一个资源组同理，一个订阅只能归属一个管理组。","D":"管理组只是治理容器，不会删除订阅。"},"rt":"管理组概述","ru":"https://learn.microsoft.com/azure/governance/management-groups/overview"},{"id":"D2-013","d":"architecture-services","t":"核心架构：资源组织层级","k":"single","q":"Azure Resource Manager（ARM）在 Azure 中扮演什么角色？","o":{"A":"监控资源性能的服务","B":"所有资源管理请求（创建、更新、删除）的统一部署和管理服务层","C":"负责资源计费的服务","D":"提供虚拟网络连接的服务"},"a":["B"],"e":"ARM 是 Azure 的管理平面：无论你通过门户、CLI、PowerShell、REST API 还是 SDK 操作资源，请求都会经过 ARM，由它进行身份验证、授权（RBAC）、策略评估，然后分发给相应的资源提供程序。这保证了所有工具产生一致的结果。","r":{"A":"监控性能的是 Azure Monitor。","C":"计费由 Cost Management + Billing 负责，ARM 只负责资源操作。","D":"网络连接由虚拟网络等网络服务提供。"},"rt":"Azure Resource Manager 概述","ru":"https://learn.microsoft.com/azure/azure-resource-manager/management/overview"},{"id":"D2-014","d":"architecture-services","t":"核心架构：资源组织层级","k":"truefalse","q":"判断：在管理组级别分配的 Azure Policy 会被其下所有的订阅和资源组继承。","o":{"A":"正确","B":"错误"},"a":["A"],"e":"正确。Azure 的治理设置（Azure Policy 分配和 RBAC 角色分配）沿层级向下继承：管理组 → 订阅 → 资源组 → 资源。因此把通用规则放在尽量高的层级，可以大幅减少重复配置。","r":{"B":"继承是管理组设计的核心价值，没有继承就失去了统一治理的意义。"},"rt":"管理组概述","ru":"https://learn.microsoft.com/azure/governance/management-groups/overview"},{"id":"D2-015","d":"architecture-services","t":"核心架构：资源组织层级","k":"single","q":"下列哪一项是 Microsoft Entra 租户（Tenant）与 Azure 订阅的正确关系？","o":{"A":"一个订阅可以关联多个 Entra 租户","B":"一个 Entra 租户可以关联多个订阅，但每个订阅只信任一个租户","C":"租户和订阅必须一一对应","D":"订阅不需要与任何租户关联"},"a":["B"],"e":"Entra 租户是身份边界，订阅是计费与访问控制边界。一个租户下可以有很多订阅（企业常见做法），但每个订阅在同一时刻只信任一个租户来进行身份验证。订阅可以在租户之间转移，但会影响已有的 RBAC 分配。","r":{"A":"订阅只能信任一个租户，不能同时关联多个。","C":"一一对应不是要求；大型企业通常在一个租户下管理数十个订阅。","D":"订阅必须关联租户，否则无法进行身份验证和授权。"},"rt":"Microsoft Entra ID 与订阅","ru":"https://learn.microsoft.com/entra/fundamentals/whatis"},{"id":"D2-016","d":"architecture-services","t":"计算服务：虚拟机与规模集","k":"single","q":"Azure 虚拟机规模集（Virtual Machine Scale Sets）的主要用途是什么？","o":{"A":"为单台虚拟机增加 CPU 和内存","B":"创建和管理一组相同配置的负载均衡虚拟机，并支持自动缩放","C":"在虚拟机之间复制磁盘","D":"把虚拟机迁移到其他区域"},"a":["B"],"e":"虚拟机规模集让你用统一配置创建一组相同的虚拟机，内置负载均衡，并可以按 CPU 使用率、队列长度等指标自动增减实例数量（水平缩放）。它是 IaaS 层面实现弹性和高可用的标准服务。","r":{"A":"为单台 VM 增加规格是垂直缩放，直接更改 VM 大小即可，与规模集无关。","C":"磁盘复制是存储功能（快照/映像），不是规模集的用途。","D":"跨区域迁移由 Azure Site Recovery 或重新部署完成。"},"rt":"虚拟机规模集概述","ru":"https://learn.microsoft.com/azure/virtual-machine-scale-sets/overview"},{"id":"D2-017","d":"architecture-services","t":"计算服务：虚拟机与规模集","k":"single","q":"可用性集（Availability Set）通过什么机制保护虚拟机免受硬件故障和计划维护的影响？","o":{"A":"跨区域复制","B":"容错域（Fault Domain）和更新域（Update Domain）","C":"异地冗余存储","D":"负载均衡器探测"},"a":["B"],"e":"可用性集把虚拟机分布到多个容错域（不同的机架，拥有独立电源和网络交换机，防止硬件单点故障）和多个更新域（分批重启，保证计划内维护时不会所有实例同时下线）。注意可用性集保护的是数据中心内部的故障，而跨数据中心故障需要可用性区域。","r":{"A":"跨区域复制属于灾难恢复范畴，不是可用性集的机制。","C":"异地冗余存储是存储层的数据复制，与虚拟机可用性集无关。","D":"负载均衡器负责流量分发和健康探测，不提供物理隔离。"},"rt":"虚拟机可用性选项","ru":"https://learn.microsoft.com/azure/virtual-machines/availability"},{"id":"D2-018","d":"architecture-services","t":"计算服务：虚拟机与规模集","k":"single","q":"下列哪种情况最适合使用 Azure 虚拟机而不是 PaaS 服务？","o":{"A":"需要完全控制操作系统并安装特定的旧版软件","B":"希望完全不管理操作系统","C":"只需要托管一个静态网站","D":"需要按执行次数计费的事件驱动函数"},"a":["A"],"e":"当应用对操作系统版本、内核参数、特殊驱动或老旧中间件有硬性依赖时，只有 IaaS 虚拟机能提供所需的控制权。其他三个场景都有更省心、更省钱的 PaaS/无服务器方案。","r":{"B":"不想管操作系统正是选择 PaaS 的理由。","C":"静态网站用 Azure 存储的静态网站托管或 App Service 更简单便宜。","D":"事件驱动、按次计费是 Azure Functions 的场景。"},"rt":"Azure 虚拟机概述","ru":"https://learn.microsoft.com/azure/virtual-machines/overview"},{"id":"D2-019","d":"architecture-services","t":"计算服务：虚拟机与规模集","k":"single","q":"Azure 虚拟桌面（Azure Virtual Desktop）提供的核心能力是什么？","o":{"A":"在云中运行容器化应用","B":"在云中提供虚拟化的桌面和应用，用户可从任意设备访问","C":"自动扩展网站实例","D":"把本地服务器纳入 Azure 治理"},"a":["B"],"e":"Azure 虚拟桌面（AVD）是桌面与应用虚拟化服务：桌面运行在云中，用户通过任意设备（含个人设备 BYOD）访问，数据不落地到终端，因此安全性更好。它还支持 Windows 多会话，让多个用户共享同一虚拟机以降低成本。","r":{"A":"运行容器化应用是 ACI/Container Apps/AKS 的职责。","C":"自动扩展网站实例是 App Service 或规模集的能力。","D":"把本地服务器纳入 Azure 治理是 Azure Arc。"},"rt":"Azure 虚拟桌面","ru":"https://learn.microsoft.com/azure/virtual-desktop/overview"},{"id":"D2-020","d":"architecture-services","t":"计算服务：虚拟机与规模集","k":"multi","q":"使用 Azure 虚拟桌面相比传统本地 VDI，下列哪两项是主要优势？（选两项）","o":{"A":"支持 Windows 多会话，多个用户共享同一台虚拟机以降低成本","B":"应用数据保存在用户的本地设备上，提高性能","C":"可以从个人设备安全访问企业桌面，数据保留在云中","D":"完全不产生任何计算费用"},"a":["A","C"],"e":"AVD 的两大卖点：①Windows 10/11 多会话——这是 Azure 独有的，可让多个并发用户共用一台会话主机，显著降低每用户成本；②集中化安全——数据和应用留在云端，终端只显示画面，即便使用个人设备（BYOD）也不会把企业数据落到本地。","r":{"B":"恰恰相反，AVD 的安全价值在于数据不落到本地设备。","D":"AVD 的会话主机是虚拟机，运行时照常产生计算和存储费用。"},"rt":"Azure 虚拟桌面","ru":"https://learn.microsoft.com/azure/virtual-desktop/overview"},{"id":"D2-021","d":"architecture-services","t":"计算服务：容器与 Kubernetes","k":"single","q":"需要以最快、最简单的方式在 Azure 中运行单个容器，不需要编排能力。应选择哪个服务？","o":{"A":"Azure Kubernetes 服务（AKS）","B":"Azure 容器实例（ACI）","C":"Azure 虚拟机","D":"Azure App Service"},"a":["B"],"e":"Azure 容器实例（ACI）是最简单的无服务器容器托管方式：给一个镜像就能秒级启动，按秒计费，不需要管理虚拟机或编排器。适合简单任务、批处理作业和构建代理。需要复杂编排（滚动升级、服务发现、自愈）时才上 AKS。","r":{"A":"AKS 提供完整的 Kubernetes 编排，但需要管理群集和节点池，对「运行单个容器」来说过重。","C":"虚拟机需要自行安装容器运行时，最慢最繁琐。","D":"App Service 也能运行容器，但它面向 Web 应用长期托管，不是运行一次性单容器的最简方案。"},"rt":"Azure 容器实例概述","ru":"https://learn.microsoft.com/azure/container-instances/container-instances-overview"},{"id":"D2-022","d":"architecture-services","t":"计算服务：容器与 Kubernetes","k":"single","q":"Azure Kubernetes 服务（AKS）为客户提供的主要价值是什么？","o":{"A":"托管的 Kubernetes 控制平面，简化容器编排群集的部署和管理","B":"提供虚拟桌面","C":"提供无服务器函数运行时","D":"提供关系型数据库"},"a":["A"],"e":"AKS 是托管的 Kubernetes：Microsoft 负责控制平面（API Server、etcd、调度器）的运行、升级和高可用，且控制平面免费；客户只为工作节点付费并管理工作负载。这大幅降低了自建 Kubernetes 的运维门槛。","r":{"B":"虚拟桌面是 Azure Virtual Desktop。","C":"无服务器函数是 Azure Functions。","D":"关系型数据库是 Azure SQL 数据库等服务。"},"rt":"Azure Kubernetes 服务","ru":"https://learn.microsoft.com/azure/aks/what-is-aks"},{"id":"D2-023","d":"architecture-services","t":"计算服务：容器与 Kubernetes","k":"single","q":"容器相对于虚拟机的核心区别是什么？","o":{"A":"容器包含完整的客户机操作系统","B":"容器共享宿主机的操作系统内核，因此更轻量、启动更快","C":"容器只能运行 Linux 应用","D":"容器不能水平扩展"},"a":["B"],"e":"虚拟机虚拟化的是硬件，每台 VM 自带一整套操作系统；容器虚拟化的是操作系统，多个容器共享宿主机内核，只打包应用及其依赖。因此容器镜像小、启动以秒计、密度高，非常适合微服务和 CI/CD。","r":{"A":"自带完整客户机操作系统的是虚拟机，这正是两者的根本差异。","C":"Windows 容器同样存在，容器不限于 Linux。","D":"容器天生适合水平扩展，这是它的优势而非限制。"},"rt":"容器与虚拟机","ru":"https://learn.microsoft.com/azure/container-instances/container-instances-overview"},{"id":"D2-024","d":"architecture-services","t":"计算服务：容器与 Kubernetes","k":"single","q":"Azure 容器应用（Azure Container Apps）最适合哪类场景？","o":{"A":"需要直接访问 Kubernetes API 做深度定制","B":"运行无服务器容器化微服务，需要自动缩放（包括缩放到零）但不想管理 Kubernetes","C":"运行 Windows 桌面会话","D":"托管关系型数据库"},"a":["B"],"e":"Azure 容器应用构建在 Kubernetes 之上，但把群集完全隐藏起来：你只提交容器，平台负责伸缩（可缩放到零）、修订管理、服务发现和流量拆分。它介于 ACI（太简单）和 AKS（太复杂）之间，适合微服务和事件驱动应用。","r":{"A":"需要直接操作 Kubernetes API 就应该选 AKS，Container Apps 不暴露群集。","C":"Windows 桌面会话是 Azure 虚拟桌面的范畴。","D":"数据库应使用 Azure SQL 数据库等托管数据服务。"},"rt":"Azure 容器应用概述","ru":"https://learn.microsoft.com/azure/container-apps/overview"},{"id":"D2-025","d":"architecture-services","t":"计算服务：Functions 与 App Service","k":"single","q":"Azure Functions 最典型的特征是什么？","o":{"A":"始终运行的长期服务","B":"由事件触发、执行完即结束，按执行次数和资源消耗计费","C":"必须先创建虚拟机","D":"只能用 C# 编写"},"a":["B"],"e":"Azure Functions 是事件驱动的无服务器计算：由 HTTP 请求、计时器、队列消息、Blob 上传等事件触发，执行短小的逻辑后结束。消耗计划下没有请求就不计费，可缩放到零；支持 C#、JavaScript、Python、Java、PowerShell 等多种语言。","r":{"A":"长期常驻的 Web 应用更适合 App Service；Functions 面向短时任务。","C":"无服务器的价值就在于不需要创建和管理虚拟机。","D":"Functions 支持多种语言，不限于 C#。"},"rt":"Azure Functions 概述","ru":"https://learn.microsoft.com/azure/azure-functions/functions-overview"},{"id":"D2-026","d":"architecture-services","t":"计算服务：Functions 与 App Service","k":"single","q":"Azure App Service 主要用于托管什么？","o":{"A":"虚拟机","B":"Web 应用、REST API 和移动后端","C":"Kubernetes 群集","D":"虚拟网络"},"a":["B"],"e":"App Service 是托管的 Web 应用平台（PaaS），可以托管网站、REST API 和移动应用后端，支持 .NET、Java、Node.js、Python、PHP 及容器。平台负责操作系统补丁、负载均衡、自动缩放、部署槽和 SSL，开发者只管代码。","r":{"A":"托管虚拟机是 Azure 虚拟机服务（IaaS）。","C":"Kubernetes 群集由 AKS 托管。","D":"虚拟网络是独立的网络服务。"},"rt":"App Service 概述","ru":"https://learn.microsoft.com/azure/app-service/overview"},{"id":"D2-027","d":"architecture-services","t":"计算服务：Functions 与 App Service","k":"multi","q":"使用 Azure App Service 托管 Web 应用可以获得下列哪两项内置能力？（选两项）","o":{"A":"自动缩放（根据负载增减实例）","B":"自动为应用编写业务代码","C":"部署槽（Deployment Slots）实现零停机发布","D":"自动设计数据库架构"},"a":["A","C"],"e":"App Service 内置的平台能力包括：自动缩放、部署槽（先部署到暂存槽验证后再交换到生产，实现零停机和快速回滚）、自定义域与托管证书、身份验证集成、持续部署集成等。业务代码和数据库设计仍然是开发者的工作。","r":{"B":"平台不会替你写业务代码。","D":"数据库架构设计属于应用设计工作，平台不代劳。"},"rt":"App Service 概述","ru":"https://learn.microsoft.com/azure/app-service/overview"},{"id":"D2-028","d":"architecture-services","t":"计算服务：Functions 与 App Service","k":"single","q":"某系统需要在收到存储账户中新上传的文件时自动执行图片压缩逻辑。最合适且最省成本的方案是？","o":{"A":"常开的虚拟机轮询存储账户","B":"由 Blob 触发器触发的 Azure Functions","C":"Azure 虚拟桌面","D":"Azure ExpressRoute"},"a":["B"],"e":"「事件发生 → 执行一段短逻辑」是 Azure Functions 的典型用例。Blob 触发器在文件上传时自动调用函数，无文件时不消耗资源也不计费，比常开虚拟机轮询省钱得多，也不需要自己写调度逻辑。","r":{"A":"常开虚拟机 24 小时计费且需要自己实现轮询和并发控制，成本与复杂度都高。","C":"虚拟桌面服务与后台事件处理完全无关。","D":"ExpressRoute 是混合网络连接服务，与此场景无关。"},"rt":"Azure Functions 概述","ru":"https://learn.microsoft.com/azure/azure-functions/functions-overview"},{"id":"D2-029","d":"architecture-services","t":"网络服务：虚拟网络","k":"single","q":"Azure 虚拟网络（VNet）的主要作用是什么？","o":{"A":"为 Azure 资源提供隔离的专用网络环境，实现资源间以及与本地网络的安全通信","B":"提供域名注册服务","C":"存储虚拟机的磁盘","D":"监控网络性能指标"},"a":["A"],"e":"虚拟网络是 Azure 中的私有网络基本构建块：它提供隔离与分段（子网）、Azure 资源之间的通信、与本地网络的通信（VPN/ExpressRoute）、与 Internet 的通信、以及流量筛选（NSG）和路由（用户定义路由）。","r":{"B":"域名注册与 DNS 托管是 Azure DNS 的职责。","C":"磁盘存储由 Azure 托管磁盘提供。","D":"网络性能监控由 Azure Monitor / 网络观察程序完成。"},"rt":"虚拟网络概述","ru":"https://learn.microsoft.com/azure/virtual-network/virtual-networks-overview"},{"id":"D2-030","d":"architecture-services","t":"网络服务：虚拟网络","k":"single","q":"两个位于不同 Azure 区域的虚拟网络需要直接通信，且流量不经过公共 Internet。应使用什么？","o":{"A":"全球虚拟网络对等互连（Global VNet Peering）","B":"点到站点 VPN","C":"Azure Bastion","D":"网络安全组"},"a":["A"],"e":"虚拟网络对等互连让两个 VNet 像在同一个网络中一样通信，流量走 Microsoft 骨干网络，不经过公共 Internet，低延迟高带宽。跨区域时称为「全球对等互连」。注意：对等互连不具备传递性（A-B、B-C 不等于 A-C 互通）。","r":{"B":"点到站点 VPN 用于单个客户端设备连接到 VNet，不是 VNet 之间的互联方案。","C":"Azure Bastion 提供通过浏览器安全访问虚拟机的能力，不做网络互联。","D":"网络安全组是流量筛选规则，不建立连接。"},"rt":"虚拟网络对等互连","ru":"https://learn.microsoft.com/azure/virtual-network/virtual-network-peering-overview"},{"id":"D2-031","d":"architecture-services","t":"网络服务：虚拟网络","k":"single","q":"网络安全组（NSG）的作用是什么？","o":{"A":"加密网络流量","B":"基于源/目标 IP、端口和协议，允许或拒绝进出子网或网络接口的流量","C":"提供跨区域的负载均衡","D":"为虚拟机分配公共 IP"},"a":["B"],"e":"网络安全组包含一组入站和出站安全规则，按优先级评估，基于源/目标 IP 地址、端口和协议允许或拒绝流量。NSG 可以关联到子网或网络接口，是 Azure 中最基础的网络层访问控制手段。","r":{"A":"加密由 VPN、TLS 等机制提供，NSG 只做筛选不做加密。","C":"跨区域负载均衡由 Traffic Manager 或 Azure Front Door 提供。","D":"公共 IP 是独立的资源，与 NSG 无关。"},"rt":"网络安全组","ru":"https://learn.microsoft.com/azure/virtual-network/network-security-groups-overview"},{"id":"D2-032","d":"architecture-services","t":"网络服务：虚拟网络","k":"single","q":"子网（Subnet）在虚拟网络中的作用是什么？","o":{"A":"把虚拟网络划分成更小的地址段，便于组织资源和分别应用安全规则","B":"提供跨区域连接","C":"加密存储数据","D":"提高虚拟机的 CPU 性能"},"a":["A"],"e":"子网把 VNet 的地址空间分段，让你按用途（如 Web 层、应用层、数据层）隔离资源，并对不同子网应用不同的 NSG 规则和路由表。某些服务（如 VPN 网关、Azure Bastion、防火墙）还要求使用特定名称的专用子网。","r":{"B":"跨区域连接由对等互连、VPN 网关或 ExpressRoute 提供。","C":"数据加密与子网划分无关。","D":"子网是网络概念，不影响计算性能。"},"rt":"虚拟网络概述","ru":"https://learn.microsoft.com/azure/virtual-network/virtual-networks-overview"},{"id":"D2-033","d":"architecture-services","t":"网络服务：混合连接","k":"single","q":"公司需要在本地数据中心与 Azure 之间建立专用的私有连接，流量完全不经过公共 Internet，并要求更高的带宽和更可靠的延迟。应选择什么？","o":{"A":"站点到站点 VPN","B":"Azure ExpressRoute","C":"点到站点 VPN","D":"虚拟网络对等互连"},"a":["B"],"e":"ExpressRoute 通过连接服务提供商建立本地与 Microsoft 云之间的专用私有链路，流量不走公共 Internet，因此可靠性更高、延迟更稳定、带宽更大（最高 100 Gbps），并且可以访问 Microsoft 365 等其他 Microsoft 云服务。代价是成本高、开通周期长。","r":{"A":"站点到站点 VPN 通过公共 Internet 建立 IPsec 加密隧道，虽然安全但延迟和带宽受公网状况影响。","C":"点到站点 VPN 面向单个客户端设备（如员工笔记本），不适合数据中心级连接。","D":"对等互连只用于连接 Azure 虚拟网络之间，不能连接本地数据中心。"},"rt":"ExpressRoute 简介","ru":"https://learn.microsoft.com/azure/expressroute/expressroute-introduction"},{"id":"D2-034","d":"architecture-services","t":"网络服务：混合连接","k":"single","q":"远程办公的员工需要从家中的笔记本电脑安全访问 Azure 虚拟网络中的资源。应使用哪种连接方式？","o":{"A":"站点到站点 VPN","B":"点到站点 VPN","C":"ExpressRoute","D":"全球对等互连"},"a":["B"],"e":"点到站点（Point-to-Site，P2S）VPN 在单个客户端设备与虚拟网络之间建立安全连接，适合远程办公、出差人员等分散的个人用户，无需在家中部署 VPN 设备。","r":{"A":"站点到站点连接的是「整个本地网络」与 VNet，需要本地 VPN 设备，不适合个人电脑。","C":"ExpressRoute 是企业级专线，为单个居家员工部署既不现实也不经济。","D":"对等互连用于 Azure VNet 之间，不服务于客户端设备接入。"},"rt":"VPN 网关概述","ru":"https://learn.microsoft.com/azure/vpn-gateway/vpn-gateway-about-vpngateways"},{"id":"D2-035","d":"architecture-services","t":"网络服务：混合连接","k":"multi","q":"关于站点到站点 VPN 与 ExpressRoute 的对比，下列哪两项正确？（选两项）","o":{"A":"站点到站点 VPN 的流量经过公共 Internet，并使用 IPsec 加密","B":"ExpressRoute 的流量不经过公共 Internet","C":"ExpressRoute 的部署速度通常比 VPN 更快、成本更低","D":"站点到站点 VPN 能提供比 ExpressRoute 更高的带宽保证"},"a":["A","B"],"e":"两者的本质差别在于传输路径：VPN 走公共 Internet 并用 IPsec 加密隧道保护，随公网状况波动；ExpressRoute 走运营商提供的专用链路，不触碰公共 Internet，带宽和延迟更可控。VPN 便宜、部署快；ExpressRoute 贵、开通周期长但性能和可靠性更好。","r":{"C":"说反了——ExpressRoute 需要与运营商协调，部署周期长且成本高。","D":"说反了——ExpressRoute 提供的带宽上限和稳定性都高于基于公网的 VPN。"},"rt":"ExpressRoute 简介","ru":"https://learn.microsoft.com/azure/expressroute/expressroute-introduction"},{"id":"D2-036","d":"architecture-services","t":"网络服务：混合连接","k":"single","q":"Azure DNS 提供什么服务？","o":{"A":"注册新的域名","B":"使用 Azure 基础结构托管 DNS 域并解析域名","C":"为虚拟机分配动态 IP","D":"过滤恶意 DNS 请求"},"a":["B"],"e":"Azure DNS 是 DNS 域的托管服务：你把域名的 DNS 记录放在 Azure 中管理，利用 Azure 的任播网络获得高可用和快速解析，并可用 RBAC、活动日志和资源锁来治理这些记录。它本身不是域名注册商。","r":{"A":"购买/注册域名需要通过域名注册商（Azure 中可用 App Service 域来购买），Azure DNS 只负责托管解析。","C":"IP 地址分配由虚拟网络的 DHCP 机制和公共 IP 资源负责。","D":"过滤恶意请求属于安全产品（如 Azure 防火墙、Defender）的能力。"},"rt":"Azure DNS 概述","ru":"https://learn.microsoft.com/azure/dns/dns-overview"},{"id":"D2-037","d":"architecture-services","t":"网络服务：混合连接","k":"single","q":"专用终结点（Private Endpoint）的作用是什么？","o":{"A":"为 Azure PaaS 服务在你的虚拟网络中分配一个专用 IP 地址，使流量不经过公共 Internet 访问该服务","B":"为虚拟机分配公共 IP 地址","C":"在 Internet 上公开虚拟网络","D":"加速静态内容分发"},"a":["A"],"e":"默认情况下，存储账户、Azure SQL 数据库等 PaaS 服务通过公共终结点访问。专用终结点在你的 VNet 子网中为该服务创建一个网络接口并分配专用 IP，访问流量走 Microsoft 骨干网，从而可以关闭公共访问，显著缩小攻击面。","r":{"B":"为虚拟机分配公共 IP 的是「公共 IP 地址」资源，与专用终结点目标相反。","C":"专用终结点的目的恰恰是减少而不是增加公开暴露。","D":"静态内容加速是 Azure 内容分发网络（CDN）/Front Door 的职责。"},"rt":"专用终结点概述","ru":"https://learn.microsoft.com/azure/private-link/private-endpoint-overview"},{"id":"D2-038","d":"architecture-services","t":"网络服务：虚拟网络","k":"single","q":"Azure 负载均衡器（Load Balancer）工作在网络模型的哪一层，主要分发什么流量？","o":{"A":"第 7 层，基于 URL 路径分发 HTTP 流量","B":"第 4 层，基于 IP 和端口分发 TCP/UDP 流量","C":"第 3 层，负责路由 IP 数据包","D":"第 2 层，负责 MAC 地址交换"},"a":["B"],"e":"Azure 负载均衡器是第 4 层（传输层）服务，按 IP 地址和端口把 TCP/UDP 流量分发到后端池，性能极高但不理解应用内容。需要按 URL 路径、主机名分发或做 Web 应用防火墙时，应使用第 7 层的应用程序网关（Application Gateway）。","r":{"A":"基于 URL 路径分发是应用程序网关（第 7 层）的能力。","C":"第 3 层路由由 Azure 的系统路由和用户定义路由完成。","D":"第 2 层交换属于物理网络，客户不可见。"},"rt":"Azure 负载均衡器概述","ru":"https://learn.microsoft.com/azure/load-balancer/load-balancer-overview"},{"id":"D2-039","d":"architecture-services","t":"网络服务：虚拟网络","k":"truefalse","q":"判断：默认情况下，同一个虚拟网络中不同子网的资源之间可以直接通信。","o":{"A":"正确","B":"错误"},"a":["A"],"e":"正确。同一 VNet 内的所有子网默认互通，Azure 会自动创建系统路由实现这一点。如果需要隔离子网之间的流量，必须显式使用网络安全组规则或 Azure 防火墙来阻断。","r":{"B":"默认互通是 Azure 虚拟网络的既定行为；「默认隔离」是需要自己配置 NSG 才能实现的。"},"rt":"虚拟网络概述","ru":"https://learn.microsoft.com/azure/virtual-network/virtual-networks-overview"},{"id":"D2-040","d":"architecture-services","t":"存储服务：存储账户与冗余","k":"single","q":"本地冗余存储（LRS）提供什么级别的数据保护？","o":{"A":"在单个数据中心内保存三个数据副本","B":"在三个可用性区域各保存一个副本","C":"在两个 Azure 区域各保存三个副本","D":"只保存一个副本"},"a":["A"],"e":"LRS 在主要区域的单个物理位置（一个数据中心）内同步复制三个副本，是成本最低的冗余选项，可防御磁盘、机架、服务器级别的故障，但无法抵御整个数据中心的灾难。适合可重建的非关键数据。","r":{"B":"在三个可用性区域各存一个副本的是 ZRS（区域冗余存储）。","C":"跨两个区域复制的是 GRS/GZRS。","D":"任何 Azure 存储冗余选项都不止一个副本，最少是三个。"},"rt":"Azure 存储冗余","ru":"https://learn.microsoft.com/azure/storage/common/storage-redundancy"},{"id":"D2-041","d":"architecture-services","t":"存储服务：存储账户与冗余","k":"single","q":"需要数据在单个数据中心发生故障时仍然可用，但不需要跨区域保护。应选择哪种冗余？","o":{"A":"LRS","B":"ZRS","C":"GRS","D":"RA-GRS"},"a":["B"],"e":"区域冗余存储（ZRS）把数据同步复制到主要区域内的三个可用性区域，因此单个数据中心（可用性区域）整体故障时数据仍可读写，同时数据不出区域，满足数据驻留要求。","r":{"A":"LRS 的三个副本都在同一个数据中心内，该数据中心故障时数据不可用。","C":"GRS 会把数据复制到另一个区域，提供的保护超出需求，且数据出境可能违反数据驻留要求。","D":"RA-GRS 同样是跨区域方案，并额外提供对次要区域的读访问，超出本题需求。"},"rt":"Azure 存储冗余","ru":"https://learn.microsoft.com/azure/storage/common/storage-redundancy"},{"id":"D2-042","d":"architecture-services","t":"存储服务：存储账户与冗余","k":"single","q":"异地冗余存储（GRS）的数据复制方式是？","o":{"A":"在主要区域使用 LRS 三副本，并异步复制到配对的次要区域再做 LRS 三副本","B":"在主要区域使用 ZRS，并同步复制到次要区域","C":"只在次要区域保存数据","D":"在同一区域的三个可用性区域之间复制"},"a":["A"],"e":"GRS = 主要区域 LRS（3 副本）+ 异步复制到配对的次要区域再做 LRS（3 副本），共 6 个副本，提供约 16 个 9 的持久性。注意复制到次要区域是「异步」的，因此发生区域级灾难时可能丢失少量最新数据。默认情况下次要区域的数据不可读，需要 RA-GRS 才能读。","r":{"B":"主要区域使用 ZRS 再复制到次要区域的是 GZRS，不是 GRS。","C":"主要区域始终保有数据，次要区域是额外的副本。","D":"只在区域内三个可用性区域之间复制的是 ZRS。"},"rt":"Azure 存储冗余","ru":"https://learn.microsoft.com/azure/storage/common/storage-redundancy"},{"id":"D2-043","d":"architecture-services","t":"存储服务：存储账户与冗余","k":"single","q":"应用需要在主要区域不可用时，仍能从次要区域读取数据。应选择哪种冗余选项？","o":{"A":"LRS","B":"ZRS","C":"GRS","D":"RA-GRS"},"a":["D"],"e":"只有带「RA（Read-Access，读取访问）」前缀的选项——RA-GRS 和 RA-GZRS——才允许应用直接从次要区域读取数据。普通 GRS/GZRS 的次要副本平时不可访问，只有在 Microsoft 发起故障转移后才可用。","r":{"A":"LRS 只在单个数据中心内，没有次要区域。","B":"ZRS 不跨区域复制，没有次要区域可读。","C":"GRS 有次要副本，但默认不可读取，必须故障转移后才能访问。"},"rt":"Azure 存储冗余","ru":"https://learn.microsoft.com/azure/storage/common/storage-redundancy"},{"id":"D2-044","d":"architecture-services","t":"存储服务：存储账户与冗余","k":"single","q":"提供最高持久性和可用性的存储冗余选项是？","o":{"A":"LRS","B":"ZRS","C":"GRS","D":"GZRS / RA-GZRS"},"a":["D"],"e":"GZRS 结合了两种能力：主要区域内用 ZRS 跨三个可用性区域同步复制（抵御数据中心故障），再异步复制到次要区域做 LRS（抵御区域级灾难）。RA-GZRS 还额外允许读取次要区域，是 Azure 存储中保护级别最高的选项。","r":{"A":"LRS 保护级别最低，只覆盖单个数据中心内的故障。","B":"ZRS 无法抵御整个区域的灾难。","C":"GRS 主要区域内仍是 LRS，抵御不了主要区域的数据中心级故障。"},"rt":"Azure 存储冗余","ru":"https://learn.microsoft.com/azure/storage/common/storage-redundancy"},{"id":"D2-045","d":"architecture-services","t":"存储服务：存储类型与访问层","k":"single","q":"需要存储大量图片、视频和备份文件等非结构化数据。应使用哪个 Azure 存储服务？","o":{"A":"Azure Blob 存储","B":"Azure 文件存储","C":"Azure 队列存储","D":"Azure 表存储"},"a":["A"],"e":"Blob（Binary Large Object）存储专为海量非结构化对象设计：图片、视频、日志、备份、文档等。它按对象访问（HTTP/HTTPS REST），容量几乎无限，并支持热/冷/冷存/存档访问层来优化成本。","r":{"B":"Azure 文件存储提供 SMB/NFS 文件共享，用于需要挂载为网络驱动器的场景。","C":"队列存储用于组件间的异步消息传递，不适合存大文件。","D":"表存储是 NoSQL 键值存储，用于结构化的非关系数据。"},"rt":"Azure 存储服务简介","ru":"https://learn.microsoft.com/azure/storage/common/storage-introduction"},{"id":"D2-046","d":"architecture-services","t":"存储服务：存储类型与访问层","k":"single","q":"多台虚拟机需要通过 SMB 协议访问同一个共享文件夹，并能像本地驱动器一样挂载。应使用什么？","o":{"A":"Azure Blob 存储","B":"Azure 文件存储（Azure Files）","C":"Azure 表存储","D":"Azure 托管磁盘"},"a":["B"],"e":"Azure 文件存储提供完全托管的云文件共享，支持 SMB 和 NFS 协议，可以被 Windows、Linux、macOS 以及本地服务器同时挂载，适合「多客户端共享访问」和 lift-and-shift 场景中替换本地文件服务器。","r":{"A":"Blob 存储通过 REST API 按对象访问，不能原生挂载为 SMB 共享。","C":"表存储是 NoSQL 键值数据库，与文件共享无关。","D":"托管磁盘一般只能挂载到单台虚拟机（共享磁盘是特定高级场景），不适合通用文件共享。"},"rt":"Azure 存储服务简介","ru":"https://learn.microsoft.com/azure/storage/common/storage-introduction"},{"id":"D2-047","d":"architecture-services","t":"存储服务：存储类型与访问层","k":"single","q":"数据需要保存 7 年以满足法规要求，几乎从不访问，且希望存储成本最低（可以接受取回时需要数小时）。应使用哪个访问层？","o":{"A":"热（Hot）层","B":"冷（Cool）层","C":"存档（Archive）层","D":"冷存（Cold）层"},"a":["C"],"e":"存档层是脱机层，存储成本最低，但数据不能直接读取——必须先「解冻（rehydrate）」到热层或冷层，通常需要数小时。它的最短保留期为 180 天，非常适合长期合规归档。","r":{"A":"热层存储单价最高，用于频繁访问的数据，长期归档使用极不划算。","B":"冷层适合至少 30 天不访问但仍需随时在线读取的数据，存储成本高于存档层。","D":"冷存层最短保留 90 天，成本介于冷层与存档层之间，但仍高于存档层。"},"rt":"Blob 访问层","ru":"https://learn.microsoft.com/azure/storage/blobs/access-tiers-overview"},{"id":"D2-048","d":"architecture-services","t":"存储服务：存储类型与访问层","k":"multi","q":"关于 Blob 存储访问层，下列哪两项说法正确？（选两项）","o":{"A":"热层的存储成本最高，但访问（读取）成本最低","B":"存档层的存储成本最低，但取回数据的成本和延迟最高","C":"冷层的数据无法在线读取，必须先解冻","D":"所有访问层的存储单价完全相同"},"a":["A","B"],"e":"访问层的核心权衡是「存储成本 ↔ 访问成本」：越冷的层，存着越便宜、读取越贵越慢。热层适合频繁访问，冷层/冷存层适合偶尔访问但需在线，存档层适合长期不访问的归档。","r":{"C":"冷层数据仍然是在线的、可直接读取的；必须解冻才能读的只有存档层。","D":"各层存储单价差异很大，这正是分层的意义所在。"},"rt":"Blob 访问层","ru":"https://learn.microsoft.com/azure/storage/blobs/access-tiers-overview"},{"id":"D2-049","d":"architecture-services","t":"存储服务：迁移与数据传输","k":"single","q":"公司需要把 60 TB 数据从本地迁移到 Azure，但办公室的网络带宽很小，在线传输需要数月。最合适的方案是？","o":{"A":"AzCopy","B":"Azure Data Box","C":"Azure 存储资源管理器","D":"Azure 文件同步"},"a":["B"],"e":"Azure Data Box 是物理传输设备：Microsoft 寄一台加密的存储设备到你的机房，你把数据拷进去后寄回，Microsoft 在数据中心内导入 Azure。当数据量达到 TB~PB 级而网络带宽不足时，物理运输比在线传输快得多。","r":{"A":"AzCopy 是命令行工具，仍然依赖网络带宽，无法解决带宽瓶颈。","C":"存储资源管理器是图形界面工具，同样受限于网络带宽。","D":"Azure 文件同步用于让本地文件服务器与 Azure 文件共享保持同步，不是大批量一次性迁移工具。"},"rt":"Azure Data Box","ru":"https://learn.microsoft.com/azure/databox/data-box-overview"},{"id":"D2-050","d":"architecture-services","t":"存储服务：迁移与数据传输","k":"single","q":"哪个工具用于评估本地服务器、数据库和 Web 应用，并把它们迁移到 Azure？","o":{"A":"Azure Migrate","B":"Azure Monitor","C":"Azure Advisor","D":"Azure Arc"},"a":["A"],"e":"Azure Migrate 是迁移中心：先发现和清点本地环境，再做评估（是否适合迁移、需要什么规格的 Azure 资源、预计花多少钱），最后执行服务器、数据库、Web 应用和虚拟桌面的迁移。","r":{"B":"Azure Monitor 用于监控已运行的资源，不做迁移。","C":"Azure Advisor 为已有 Azure 资源提供优化建议，不负责迁移本地负载。","D":"Azure Arc 是把本地资源纳入 Azure 治理，工作负载仍留在本地。"},"rt":"Azure Migrate 概述","ru":"https://learn.microsoft.com/azure/migrate/migrate-services-overview"},{"id":"D2-051","d":"architecture-services","t":"存储服务：迁移与数据传输","k":"single","q":"哪个命令行工具专门用于在本地与 Azure 存储之间（或存储账户之间）复制 Blob 和文件？","o":{"A":"AzCopy","B":"Azure Data Box","C":"Azure 文件同步","D":"Azure Bastion"},"a":["A"],"e":"AzCopy 是一个跨平台命令行实用工具，用于上传、下载和在存储账户之间复制 Blob/文件，支持同步、断点续传和高并发，常用于脚本化和自动化的数据搬运。","r":{"B":"Data Box 是物理设备，用于网络不足时的离线大批量迁移。","C":"Azure 文件同步用于本地文件服务器与 Azure 文件共享之间的持续同步与云分层。","D":"Azure Bastion 提供浏览器内安全访问虚拟机，与数据复制无关。"},"rt":"AzCopy 入门","ru":"https://learn.microsoft.com/azure/storage/common/storage-use-azcopy-v10"},{"id":"D2-052","d":"architecture-services","t":"存储服务：迁移与数据传输","k":"single","q":"Azure 文件同步（Azure File Sync）的主要用途是？","o":{"A":"把本地 Windows 文件服务器与 Azure 文件共享保持同步，并支持云分层节省本地空间","B":"在虚拟机之间同步磁盘","C":"同步 Entra ID 用户到本地 AD","D":"同步数据库架构"},"a":["A"],"e":"Azure 文件同步把本地 Windows 服务器变成 Azure 文件共享的一个缓存：文件在云端保留完整副本，本地服务器可以只保留最常用的文件（云分层），既保持了本地访问性能，又极大降低了本地存储需求，还天然获得了云端备份。","r":{"B":"虚拟机磁盘之间的复制由快照、映像或存储复制功能完成。","C":"把本地 AD 用户同步到 Entra ID 的是 Microsoft Entra Connect（方向也相反）。","D":"数据库架构同步属于数据库工具范畴。"},"rt":"Azure 文件同步","ru":"https://learn.microsoft.com/azure/storage/file-sync/file-sync-introduction"},{"id":"D2-053","d":"architecture-services","t":"存储服务：存储账户与冗余","k":"truefalse","q":"判断：存储账户的名称必须在整个 Azure 中全局唯一。","o":{"A":"正确","B":"错误"},"a":["A"],"e":"正确。存储账户名会构成公共访问终结点（如 https://<账户名>.blob.core.windows.net），因此必须在全球唯一，且只能使用 3–24 个小写字母和数字。类似的全局唯一要求也适用于 App Service 的默认域名等。","r":{"B":"由于账户名直接映射为公共 DNS 名称，全局唯一是硬性要求。"},"rt":"存储账户概述","ru":"https://learn.microsoft.com/azure/storage/common/storage-account-overview"},{"id":"D2-054","d":"architecture-services","t":"身份与访问：Microsoft Entra ID","k":"single","q":"Microsoft Entra ID（前身为 Azure Active Directory）的主要功能是什么？","o":{"A":"提供基于云的标识和访问管理服务","B":"提供虚拟机托管","C":"提供对象存储","D":"提供网络负载均衡"},"a":["A"],"e":"Microsoft Entra ID 是基于云的标识与访问管理服务：管理用户和组、提供身份验证（含 MFA、无密码）、单点登录、条件访问，并作为 Azure、Microsoft 365 及数千个 SaaS 应用的统一身份提供程序。它是全球性服务，不绑定某个区域。","r":{"B":"虚拟机托管是 Azure 虚拟机服务。","C":"对象存储是 Azure Blob 存储。","D":"负载均衡由 Azure 负载均衡器/应用程序网关提供。"},"rt":"Microsoft Entra ID 是什么","ru":"https://learn.microsoft.com/entra/fundamentals/whatis"},{"id":"D2-055","d":"architecture-services","t":"身份与访问：Microsoft Entra ID","k":"single","q":"组织需要让 Azure 中的虚拟机加入托管域，并使用组策略和 LDAP，但不想自己部署和维护域控制器。应使用什么？","o":{"A":"Microsoft Entra ID（仅 ID）","B":"Microsoft Entra 域服务（Entra Domain Services）","C":"Azure Arc","D":"Microsoft Entra Connect"},"a":["B"],"e":"Microsoft Entra 域服务提供托管的域服务能力：域加入、组策略、LDAP、Kerberos/NTLM 身份验证，全部由 Azure 托管，无需自己部署、修补和备份域控制器。适合需要传统 AD 功能的旧版应用上云。","r":{"A":"Entra ID 本身不提供域加入、组策略、LDAP 或 Kerberos/NTLM 这些传统 AD 能力。","C":"Azure Arc 用于将 Azure 外的资源纳入 Azure 管理，与域服务无关。","D":"Entra Connect 用于把本地 AD 的身份同步到 Entra ID，本身不提供托管域。"},"rt":"Microsoft Entra 域服务","ru":"https://learn.microsoft.com/entra/identity/domain-services/overview"},{"id":"D2-056","d":"architecture-services","t":"身份与访问：身份验证与条件访问","k":"single","q":"「身份验证（Authentication）」与「授权（Authorization）」的区别是什么？","o":{"A":"身份验证确认你是谁；授权确定你被允许做什么","B":"身份验证确定你能做什么；授权确认你是谁","C":"两者是同义词","D":"身份验证只用于管理员，授权只用于普通用户"},"a":["A"],"e":"身份验证（AuthN）回答「你是谁」——通过密码、MFA、证书等证明身份；授权（AuthZ）回答「你能做什么」——在身份确认之后，根据 RBAC 角色或策略决定可访问哪些资源、执行哪些操作。顺序永远是先验证后授权。","r":{"B":"两者的定义被颠倒了。","C":"二者是访问控制中相互独立又衔接的两个阶段，不是同义词。","D":"两者适用于所有主体（用户、组、服务主体、托管标识），与角色无关。"},"rt":"身份验证与授权","ru":"https://learn.microsoft.com/entra/identity-platform/authentication-vs-authorization"},{"id":"D2-057","d":"architecture-services","t":"身份与访问：身份验证与条件访问","k":"single","q":"多重身份验证（MFA）要求用户提供来自至少几类凭据的证明？","o":{"A":"同一类别的两个不同凭据","B":"两个或以上不同类别的凭据（你知道的、你拥有的、你本身的）","C":"三个密码","D":"一个密码和一个用户名"},"a":["B"],"e":"MFA 要求组合不同「类别」的凭据：①你知道的（密码、PIN）②你拥有的（手机、令牌、FIDO2 密钥）③你本身的（指纹、面部）。关键在于跨类别——两个密码不构成 MFA，因为攻击者窃取密码库就能同时获得两者。","r":{"A":"同类别的两个凭据不构成多重身份验证，防护价值有限。","C":"多个密码都属于「你知道的」这一类，不算多重。","D":"用户名是标识而非凭据，密码 + 用户名只是单因素验证。"},"rt":"MFA 工作原理","ru":"https://learn.microsoft.com/entra/identity/authentication/concept-mfa-howitworks"},{"id":"D2-058","d":"architecture-services","t":"身份与访问：身份验证与条件访问","k":"multi","q":"下列哪两项属于无密码（Passwordless）身份验证方式？（选两项）","o":{"A":"Windows Hello 企业版","B":"短信接收的一次性密码作为第二因素","C":"FIDO2 安全密钥","D":"长度 16 位的复杂密码"},"a":["A","C"],"e":"无密码验证完全去掉密码这一环节，改用「设备 + 生物识别/PIN」的组合。Microsoft 支持的三种无密码方式是：Windows Hello 企业版、Microsoft Authenticator 应用（无密码登录）、FIDO2 安全密钥。它们既更安全（无密码可被钓鱼或撞库）又更便捷。","r":{"B":"短信一次性密码是 MFA 的第二因素，前提仍然是先输入密码，因此不是无密码方式，而且 SMS 易受 SIM 劫持攻击。","D":"再复杂的密码也仍然是密码，不属于无密码方式。"},"rt":"无密码身份验证","ru":"https://learn.microsoft.com/entra/identity/authentication/concept-authentication-passwordless"},{"id":"D2-059","d":"architecture-services","t":"身份与访问：身份验证与条件访问","k":"single","q":"条件访问（Conditional Access）的工作原理最准确的描述是？","o":{"A":"始终阻止来自外部网络的所有访问","B":"收集用户、设备、位置、应用和风险等信号，据此决定允许访问、要求额外验证或阻止访问","C":"自动为所有用户重置密码","D":"对所有数据进行加密"},"a":["B"],"e":"条件访问是「如果…则…」的策略引擎：先收集信号（谁在登录、用什么设备、从哪个位置/IP、访问什么应用、风险等级如何），然后作出决策（允许、要求 MFA、要求合规设备、阻止）。它是实现零信任「显式验证」原则的核心工具。","r":{"A":"条件访问是基于条件的细粒度决策，而不是一刀切地阻止外部访问。","C":"密码重置是自助密码重置（SSPR）功能，不是条件访问。","D":"数据加密是独立的安全机制，与访问决策无关。"},"rt":"条件访问概述","ru":"https://learn.microsoft.com/entra/identity/conditional-access/overview"},{"id":"D2-060","d":"architecture-services","t":"身份与访问：身份验证与条件访问","k":"single","q":"单点登录（SSO）带来的主要安全好处是什么？","o":{"A":"用户需要记住更多密码","B":"用户只需维护一组凭据，减少密码疲劳和弱密码/重复使用密码的风险","C":"完全消除了对身份验证的需要","D":"让每个应用各自管理自己的密码策略"},"a":["B"],"e":"SSO 让用户用一组凭据访问多个应用。安全价值在于：密码数量减少 → 用户不再因为记不住而设置弱密码或到处重复使用 → 同时企业可以把 MFA、条件访问等强保护集中施加在这一个身份上。代价是这组凭据一旦泄露影响面大，因此必须配合 MFA。","r":{"A":"SSO 的目的恰恰是减少需要记忆的凭据数量。","C":"SSO 仍然需要身份验证，只是验证一次后可复用。","D":"SSO 是把身份验证集中化，而不是让各应用各自为政。"},"rt":"什么是单点登录","ru":"https://learn.microsoft.com/entra/identity/enterprise-apps/what-is-single-sign-on"},{"id":"D2-061","d":"architecture-services","t":"身份与访问：RBAC 基于角色的访问控制","k":"single","q":"基于角色的访问控制（RBAC）中的「角色分配」由哪三个要素构成？","o":{"A":"用户、密码、时间","B":"安全主体、角色定义、范围","C":"订阅、资源组、资源","D":"网络、存储、计算"},"a":["B"],"e":"一个 RBAC 角色分配 = 安全主体（谁：用户/组/服务主体/托管标识）+ 角色定义（能做什么：如「参与者」）+ 范围（在哪里生效：管理组/订阅/资源组/资源）。权限沿范围向下继承，并且多个分配是叠加（累加）的。","r":{"A":"密码和时间不是角色分配的组成部分。","C":"这三项都属于「范围」的可选层级，只构成三要素中的一个。","D":"这是资源类别，与 RBAC 的构成无关。"},"rt":"Azure RBAC 概述","ru":"https://learn.microsoft.com/azure/role-based-access-control/overview"},{"id":"D2-062","d":"architecture-services","t":"身份与访问：RBAC 基于角色的访问控制","k":"single","q":"需要让审计人员能够查看某个订阅中的所有资源，但不能做任何修改。应分配哪个内置角色？","o":{"A":"所有者（Owner）","B":"参与者（Contributor）","C":"读者（Reader）","D":"用户访问管理员"},"a":["C"],"e":"「读者」角色只能查看资源，不能创建、修改或删除，完全符合最小权限原则下的审计需求。记住三个核心内置角色的阶梯：所有者（全部权限 + 可授予他人权限）> 参与者（可管理资源但不能授权）> 读者（只读）。","r":{"A":"所有者拥有完全权限并能授予他人权限，远超审计需要，违反最小权限原则。","B":"参与者可以创建和删除资源，不符合「不能修改」的要求。","D":"用户访问管理员专门用于管理他人的访问权限，不是只读查看角色。"},"rt":"Azure 内置角色","ru":"https://learn.microsoft.com/azure/role-based-access-control/built-in-roles"},{"id":"D2-063","d":"architecture-services","t":"身份与访问：RBAC 基于角色的访问控制","k":"single","q":"在订阅级别为某用户分配了「参与者」角色。该用户对订阅下新建的资源组拥有什么权限？","o":{"A":"没有任何权限，需要单独分配","B":"自动继承参与者权限","C":"只有读取权限","D":"拥有者权限"},"a":["B"],"e":"RBAC 权限沿层级向下继承：在订阅级别分配的角色自动适用于该订阅下的所有资源组和资源，包括之后新建的。这既是便利也是风险——在高层级授予宽泛权限会意外覆盖大量资源，因此应尽量在最小必要范围分配。","r":{"A":"继承是 RBAC 的默认行为，无需重复分配。","C":"继承的是所分配角色的完整权限，不会降级为只读。","D":"继承不会提升权限级别，参与者不会变成所有者。"},"rt":"Azure RBAC 概述","ru":"https://learn.microsoft.com/azure/role-based-access-control/overview"},{"id":"D2-064","d":"architecture-services","t":"身份与访问：RBAC 基于角色的访问控制","k":"truefalse","q":"判断：Azure RBAC 的多个角色分配是叠加的——用户的有效权限是其所有角色分配的并集。","o":{"A":"正确","B":"错误"},"a":["A"],"e":"正确。RBAC 是累加模型：如果用户在资源组上是「读者」、在其中某个资源上是「参与者」，那么他对该资源拥有参与者权限。要显式剥夺权限需要使用「拒绝分配」（deny assignment），而拒绝分配的优先级高于角色分配。","r":{"B":"RBAC 默认是允许累加的模型，只有拒绝分配才会覆盖它。"},"rt":"Azure RBAC 概述","ru":"https://learn.microsoft.com/azure/role-based-access-control/overview"},{"id":"D2-065","d":"architecture-services","t":"安全：零信任与纵深防御","k":"multi","q":"零信任（Zero Trust）模型的指导原则包括下列哪两项？（选两项）","o":{"A":"显式验证（Verify explicitly）","B":"信任企业网络内部的所有流量","C":"使用最小权限访问（Use least privilege access）","D":"只在边界部署防火墙即可"},"a":["A","C"],"e":"零信任的三大原则是：①显式验证——每次访问都基于所有可用信号（身份、设备、位置、风险）进行验证；②最小权限访问——只给完成工作所需的最低权限，并配合实时（JIT）和恰足（JEA）访问；③假定已泄露（Assume breach）——按照攻击者已在网络内的前提设计防御，进行分段和加密。","r":{"B":"「默认信任内网」正是传统边界安全模型的前提，零信任明确否定它——「永不信任，始终验证」。","D":"只靠边界防火墙是传统城堡护城河模型，零信任要求在每一层都验证。"},"rt":"零信任概述","ru":"https://learn.microsoft.com/security/zero-trust/zero-trust-overview"},{"id":"D2-066","d":"architecture-services","t":"安全：零信任与纵深防御","k":"single","q":"「纵深防御（Defense in Depth）」策略的核心思想是什么？","o":{"A":"只在网络边界部署最强的防护","B":"使用多层防护机制，任何一层被突破后仍有其他层继续提供保护","C":"把所有数据存放在一个受保护的位置","D":"只依赖加密来保护所有资产"},"a":["B"],"e":"纵深防御通过分层来消除单点失效：物理安全 → 标识与访问 → 外围（DDoS 防护、防火墙）→ 网络（分段、限制通信）→ 计算（补丁、终结点保护）→ 应用程序（安全开发、无嵌入机密）→ 数据（加密、分类）。每一层都减缓攻击并提供检测机会。","r":{"A":"只加固边界正是纵深防御要克服的单点失效问题。","C":"把资产集中在一处反而形成单点失效，与分层防御无关。","D":"加密只是数据层的一种手段，无法替代其他层的防护。"},"rt":"纵深防御","ru":"https://learn.microsoft.com/azure/security/fundamentals/overview"},{"id":"D2-067","d":"architecture-services","t":"安全：零信任与纵深防御","k":"single","q":"在纵深防御的分层模型中，位于最内层、也是最终要保护的对象通常是什么？","o":{"A":"物理安全","B":"网络层","C":"数据","D":"外围层"},"a":["C"],"e":"纵深防御的各层最终都服务于一个目的：保护数据。数据是攻击者的目标，也是法规要求企业承担责任的对象。因此数据层的加密、分类、访问控制是整个防御体系的核心，其余各层都是外围屏障。","r":{"A":"物理安全是最外层的第一道屏障，不是最内层。","B":"网络层处于中间位置，用于分段和限制通信。","D":"外围层负责 DDoS 防护和边界过滤，属于外部层次。"},"rt":"纵深防御","ru":"https://learn.microsoft.com/azure/security/fundamentals/overview"},{"id":"D2-068","d":"architecture-services","t":"安全：零信任与纵深防御","k":"single","q":"Microsoft Defender for Cloud 提供的核心能力是什么？","o":{"A":"提供云工作负载的安全态势管理与威胁防护，并给出安全分数和改进建议","B":"托管虚拟机","C":"管理成本预算","D":"托管 DNS 记录"},"a":["A"],"e":"Defender for Cloud 同时是 CSPM（云安全态势管理）和 CWP（云工作负载保护）平台：它持续评估资源配置、用「安全分数（Secure Score）」量化态势、给出具体修复建议、提供法规合规仪表板，并对虚拟机、存储、数据库、容器等提供威胁检测。借助 Azure Arc 还可覆盖本地和其他云。","r":{"B":"托管虚拟机是计算服务的职责。","C":"预算管理是 Microsoft Cost Management 的功能。","D":"DNS 托管是 Azure DNS 的功能。"},"rt":"Defender for Cloud 简介","ru":"https://learn.microsoft.com/azure/defender-for-cloud/defender-for-cloud-introduction"},{"id":"D2-069","d":"architecture-services","t":"安全：零信任与纵深防御","k":"single","q":"Microsoft Defender for Cloud 中的「安全分数（Secure Score）」用来做什么？","o":{"A":"衡量资源的性能","B":"量化当前安全态势，并按改进效果排序给出修复建议","C":"计算每月的 Azure 费用","D":"评估网络带宽利用率"},"a":["B"],"e":"安全分数把当前环境与 Microsoft 云安全基准做对比，用一个百分比量化安全态势，并把待修复项按「修复后能提升多少分」排序，让团队知道先做哪件事收益最大。它是把安全工作变成可跟踪、可汇报指标的关键机制。","r":{"A":"性能指标由 Azure Monitor 提供。","C":"费用由 Cost Management 计算。","D":"带宽利用率属于网络监控指标。"},"rt":"Defender for Cloud 简介","ru":"https://learn.microsoft.com/azure/defender-for-cloud/defender-for-cloud-introduction"},{"id":"D2-070","d":"architecture-services","t":"安全：零信任与纵深防御","k":"single","q":"下列哪项最能体现零信任中的「假定已泄露（Assume breach）」原则？","o":{"A":"默认信任来自公司办公网络的流量","B":"对网络进行微分段并对内部流量加密，限制横向移动","C":"只在外网入口部署防火墙","D":"为所有用户分配所有者角色以便于工作"},"a":["B"],"e":"「假定已泄露」要求按照攻击者已经在内部的前提来设计：最小化爆炸半径（微分段）、端到端加密、验证每一次访问、持续分析遥测以发现异常。目标是让攻击者即使进入也无法横向移动和扩大战果。","r":{"A":"默认信任内网流量是被零信任明确否定的传统假设。","C":"仅靠边界防火墙无法应对已经进入内部的攻击者。","D":"普发高权限与最小权限原则完全相悖，会极大放大泄露后果。"},"rt":"零信任概述","ru":"https://learn.microsoft.com/security/zero-trust/zero-trust-overview"},{"id":"D2-071","d":"architecture-services","t":"身份与访问：Microsoft Entra ID","k":"single","q":"托管标识（Managed Identity）解决的主要问题是什么？","o":{"A":"让 Azure 资源在访问其他 Azure 服务时无需在代码或配置中保存凭据","B":"为用户提供单点登录","C":"加密虚拟机磁盘","D":"过滤网络流量"},"a":["A"],"e":"托管标识由 Azure 自动在 Entra ID 中创建和维护身份，并自动轮换凭据。应用（如虚拟机上的程序或 App Service）可以直接用这个身份去访问存储、密钥保管库等服务，从而彻底消除「把连接字符串和密钥写在代码或配置文件里」这一常见安全隐患。","r":{"B":"单点登录面向的是用户登录多个应用，托管标识面向的是服务到服务的身份。","C":"磁盘加密由 Azure 磁盘加密/平台托管密钥负责。","D":"网络流量过滤由 NSG 和防火墙负责。"},"rt":"托管标识概述","ru":"https://learn.microsoft.com/entra/identity/managed-identities-azure-resources/overview"},{"id":"D2-072","d":"architecture-services","t":"安全：零信任与纵深防御","k":"single","q":"Azure Key Vault 的用途是什么？","o":{"A":"集中安全地存储和管理机密、密钥与证书，并控制访问权限","B":"存储虚拟机的操作系统磁盘","C":"存储应用日志","D":"存储备份文件"},"a":["A"],"e":"Key Vault 是托管的机密管理服务：集中保管密码、连接字符串、加密密钥和 TLS/SSL 证书，支持硬件安全模块（HSM）保护、访问审计、密钥轮换和细粒度访问控制。配合托管标识使用，可以让应用完全不接触明文机密。","r":{"B":"虚拟机磁盘由托管磁盘服务提供。","C":"日志存储在 Log Analytics 工作区或存储账户中。","D":"备份由 Azure 备份服务和恢复服务保管库负责。"},"rt":"Azure Key Vault 概述","ru":"https://learn.microsoft.com/azure/key-vault/general/overview"},{"id":"D3-001","d":"management-governance","t":"成本管理：影响因素与优化","k":"multi","q":"下列哪两项会影响 Azure 资源的成本？（选两项）","o":{"A":"资源部署所在的区域（地理位置）","B":"资源组的名称长度","C":"出站网络流量（数据传出）的大小","D":"订阅所使用的语言设置"},"a":["A","C"],"e":"影响 Azure 成本的主要因素包括：资源类型、使用量（消耗）、区域（不同区域单价不同）、网络流量（出站数据传输通常收费，入站通常免费）、订阅类型、以及 Azure 市场中的第三方产品。","r":{"B":"资源组和资源的命名不影响计费。","D":"门户语言等显示设置与费用无关。"},"rt":"Azure 成本管理概述","ru":"https://learn.microsoft.com/azure/cost-management-billing/costs/overview-cost-management"},{"id":"D3-002","d":"management-governance","t":"成本管理：影响因素与优化","k":"single","q":"工作负载稳定运行且预计将持续三年。哪种方式能最有效地降低虚拟机成本？","o":{"A":"使用即用即付定价","B":"购买预留实例（Azure Reservations）","C":"使用现成（Spot）虚拟机","D":"把虚拟机部署到更多区域"},"a":["B"],"e":"预留实例通过承诺使用 1 年或 3 年来换取大幅折扣（相对即用即付最高可省约 72%），非常适合长期稳定运行的可预测工作负载。如果还持有带软件保障的 Windows Server/SQL Server 许可证，再叠加 Azure 混合权益可以进一步降本。","r":{"A":"即用即付是单价最高的方式，适合短期或波动负载，不适合长期稳定负载。","C":"Spot 虚拟机价格低但可能被随时收回，只适合可中断的批处理任务，不适合稳定运行的生产负载。","D":"部署到更多区域会增加而不是减少成本。"},"rt":"Azure 预留","ru":"https://learn.microsoft.com/azure/cost-management-billing/reservations/save-compute-costs-reservations"},{"id":"D3-003","d":"management-governance","t":"成本管理：影响因素与优化","k":"single","q":"Azure 混合权益（Azure Hybrid Benefit）可以带来什么好处？","o":{"A":"利用已有的带软件保障的 Windows Server / SQL Server 许可证，在 Azure 中降低相应的许可成本","B":"免费获得无限的存储空间","C":"免除所有网络出站流量费用","D":"把本地服务器迁移到 Azure"},"a":["A"],"e":"Azure 混合权益允许你把已购买的、带软件保障（Software Assurance）的 Windows Server 和 SQL Server 许可证带到云上使用，从而只支付计算部分的费用，显著降低总成本。它是纯粹的许可优化手段。","r":{"B":"存储始终按用量计费，没有无限免费额度。","C":"出站流量费用不受许可权益影响。","D":"迁移工作由 Azure Migrate 等工具完成，混合权益只涉及许可计费。"},"rt":"Azure 混合权益","ru":"https://learn.microsoft.com/azure/cost-management-billing/scope-level/"},{"id":"D3-004","d":"management-governance","t":"成本管理：影响因素与优化","k":"single","q":"关于 Azure 的数据传输费用，下列说法正确的是？","o":{"A":"入站（进入 Azure）和出站（离开 Azure）数据都收费","B":"入站数据通常免费，出站数据通常收费","C":"入站数据收费，出站数据免费","D":"所有数据传输都免费"},"a":["B"],"e":"Azure 的通用规则是：数据传入（ingress）不收费，数据传出（egress，离开 Azure 数据中心或跨区域传输）按流量收费。这是设计架构时的重要考量——比如跨区域复制和多云架构会产生可观的出站流量成本。","r":{"A":"入站流量通常不收费。","C":"方向完全说反了。","D":"出站流量是实实在在的计费项。"},"rt":"带宽定价","ru":"https://learn.microsoft.com/azure/cost-management-billing/understand/understand-azure-marketplace-charges"},{"id":"D3-005","d":"management-governance","t":"成本管理：计算器与 Cost Management","k":"single","q":"在把工作负载部署到 Azure 之前，想估算计划中的虚拟机、存储和带宽每月大约花多少钱。应使用什么工具？","o":{"A":"定价计算器（Pricing Calculator）","B":"TCO 计算器","C":"Azure Advisor","D":"Cost Management 的成本分析"},"a":["A"],"e":"定价计算器用于「尚未部署」的资源做费用估算：选择服务、区域、规格和数量，即可得到预估月度成本，还能保存和分享估算方案。注意它只估算 Azure 侧的成本，不与本地做对比。","r":{"B":"TCO 计算器用于「本地环境 vs Azure」的总拥有成本对比，包含硬件、电力、人力等本地成本，目的不同。","C":"Advisor 是针对已部署资源给出优化建议，无法估算尚未存在的资源。","D":"成本分析展示的是已经产生的实际费用，不能预估未部署资源。"},"rt":"定价计算器","ru":"https://learn.microsoft.com/azure/cost-management-billing/understand/pricing-calculator"},{"id":"D3-006","d":"management-governance","t":"成本管理：计算器与 Cost Management","k":"single","q":"管理层希望比较「继续维护本地数据中心」与「迁移到 Azure」在未来几年的总成本差异。应使用什么工具？","o":{"A":"定价计算器","B":"总拥有成本（TCO）计算器","C":"Azure Monitor","D":"Azure Policy"},"a":["B"],"e":"TCO 计算器专门用于「本地 vs Azure」的总拥有成本对比：你输入现有服务器、数据库、存储和网络规模，它会估算本地的硬件、软件、电力、制冷、机房和人力成本，并与等效的 Azure 成本做多年对比，输出可用于商业论证的报告。","r":{"A":"定价计算器只估算 Azure 的费用，不计算本地数据中心成本，无法做对比。","C":"Azure Monitor 用于监控运行中的资源，与成本对比无关。","D":"Azure Policy 用于合规治理，与成本测算无关。"},"rt":"TCO 计算器","ru":"https://learn.microsoft.com/azure/cloud-adoption-framework/strategy/cloud-migration-business-case"},{"id":"D3-007","d":"management-governance","t":"成本管理：计算器与 Cost Management","k":"multi","q":"Microsoft Cost Management 提供下列哪两项能力？（选两项）","o":{"A":"分析和可视化历史与当前的实际花费","B":"自动重构应用程序代码以降低成本","C":"创建预算并在花费接近阈值时发送警报","D":"自动删除超出预算的资源"},"a":["A","C"],"e":"Cost Management 的核心能力是「看清楚 + 管得住」：成本分析（按订阅、资源组、标记、服务等维度切分历史花费）、预算与警报（达到阈值时通知）、成本建议、成本分摊和数据导出。","r":{"B":"优化代码是开发团队的工作，工具不会自动重构应用。","D":"预算警报只发送通知，默认不会自动删除资源（可以自行配置自动化操作，但这不是内置默认行为）。"},"rt":"Azure 成本管理概述","ru":"https://learn.microsoft.com/azure/cost-management-billing/costs/overview-cost-management"},{"id":"D3-008","d":"management-governance","t":"成本管理：标记（Tags）","k":"single","q":"Azure 标记（Tags）的主要用途是什么？","o":{"A":"提高资源的运行性能","B":"为资源附加键值对元数据，用于分类、成本分摊和自动化","C":"加密资源数据","D":"限制资源所在的区域"},"a":["B"],"e":"标记是附加在资源上的「键:值」元数据，如 Environment:Production、CostCenter:Finance、Owner:张三。它们让你可以按业务维度筛选资源、在成本分析中按部门/项目分摊费用，并作为自动化脚本和策略的判断依据。","r":{"A":"标记纯粹是元数据，对性能没有任何影响。","C":"加密由存储加密、Key Vault 等机制实现，与标记无关。","D":"限制部署区域由 Azure Policy 实现，不是标记本身的功能。"},"rt":"使用标记组织资源","ru":"https://learn.microsoft.com/azure/azure-resource-manager/management/tag-resources"},{"id":"D3-009","d":"management-governance","t":"成本管理：标记（Tags）","k":"single","q":"关于标记的继承，下列说法正确的是？","o":{"A":"资源会自动继承其资源组的标记","B":"资源默认不会继承资源组的标记，但可以用 Azure Policy 强制附加","C":"标记只能应用于订阅级别","D":"标记一旦设置就无法修改"},"a":["B"],"e":"这是高频陷阱：Azure 中的标记默认不继承——给资源组打了标记，其中的资源并不会自动获得。要实现统一打标，通常用 Azure Policy 的 modify/append 效果，在资源创建或修复时自动补上所需标记。","r":{"A":"默认不继承，这正是很多人成本分摊算不准的原因。","C":"标记可用于订阅、资源组和大多数资源，不限于订阅级别。","D":"标记可以随时添加、修改和删除。"},"rt":"使用标记组织资源","ru":"https://learn.microsoft.com/azure/azure-resource-manager/management/tag-resources"},{"id":"D3-010","d":"management-governance","t":"成本管理：影响因素与优化","k":"single","q":"财务部门希望在 Azure 月度花费达到预算的 80% 时收到邮件通知。应配置什么？","o":{"A":"Azure Policy 规则","B":"Cost Management 中的预算与预算警报","C":"资源锁","D":"Azure Service Health 警报"},"a":["B"],"e":"在 Cost Management 中创建预算（Budget），设置金额、周期和范围（订阅/资源组/管理组），并配置在达到某个百分比阈值时触发操作组发送邮件或调用自动化。这是控制超支的标准做法。","r":{"A":"Azure Policy 控制的是资源配置合规，不监控花费金额。","C":"资源锁防止资源被误删或修改，与成本无关。","D":"Service Health 警报通知的是 Azure 服务故障和计划维护，不是花费。"},"rt":"创建和管理预算","ru":"https://learn.microsoft.com/azure/cost-management-billing/costs/tutorial-acm-create-budgets"},{"id":"D3-011","d":"management-governance","t":"治理与合规：Azure Policy 与资源锁","k":"single","q":"需要确保团队只能在「中国东部」和「东南亚」两个区域创建资源。应使用什么？","o":{"A":"资源锁","B":"Azure Policy","C":"RBAC 读者角色","D":"管理组"},"a":["B"],"e":"Azure Policy 用于对资源属性强制执行规则：内置的「允许的位置」策略可以拒绝在指定区域之外创建资源。Policy 关注「资源应该是什么样」，而 RBAC 关注「谁可以做什么」，两者互补。","r":{"A":"资源锁只能防止删除或修改已有资源，无法限制新资源的部署位置。","C":"RBAC 控制的是用户权限，无法表达「只能部署在某些区域」这样的资源属性约束。","D":"管理组是治理层级容器，本身不含规则，需要配合 Azure Policy 才能生效。"},"rt":"Azure Policy 概述","ru":"https://learn.microsoft.com/azure/governance/policy/overview"},{"id":"D3-012","d":"management-governance","t":"治理与合规：Azure Policy 与资源锁","k":"single","q":"Azure Policy 与 Azure RBAC 的核心区别是什么？","o":{"A":"Policy 控制用户能做什么，RBAC 控制资源属性","B":"Policy 控制资源的属性和配置是否合规，RBAC 控制谁可以对资源执行哪些操作","C":"两者完全相同","D":"Policy 只能用于虚拟机"},"a":["B"],"e":"记忆方式：RBAC 管「人和权限」（谁能创建虚拟机），Azure Policy 管「资源和配置」（创建出来的虚拟机必须打标记、必须在指定区域、不能使用某些规格）。一个用户即使有权限创建资源，仍可能被 Policy 拒绝。","r":{"A":"两者的职责被颠倒了。","C":"两者是互补的独立机制，评估的对象完全不同。","D":"Azure Policy 适用于几乎所有资源类型。"},"rt":"Azure Policy 概述","ru":"https://learn.microsoft.com/azure/governance/policy/overview"},{"id":"D3-013","d":"management-governance","t":"治理与合规：Azure Policy 与资源锁","k":"single","q":"Azure Policy 中的「计划（Initiative，又称策略集）」是什么？","o":{"A":"一个用于部署资源的模板","B":"一组相关策略定义的集合，可作为整体分配以实现某个合规目标","C":"资源的成本预算","D":"虚拟机的维护计划"},"a":["B"],"e":"计划把多个策略定义打包在一起统一分配和跟踪合规性。例如「ISO 27001」或「启用 Defender for Cloud 全部监视」这类计划包含几十上百条策略，按计划分配比逐条分配更易管理，也更便于查看整体合规得分。","r":{"A":"部署资源的模板是 ARM 模板或 Bicep 文件。","C":"成本预算属于 Cost Management。","D":"虚拟机维护计划属于更新管理范畴。"},"rt":"Azure Policy 概述","ru":"https://learn.microsoft.com/azure/governance/policy/overview"},{"id":"D3-014","d":"management-governance","t":"治理与合规：Azure Policy 与资源锁","k":"single","q":"需要防止生产环境中的一个关键存储账户被任何人意外删除，包括订阅所有者。应使用什么？","o":{"A":"CanNotDelete（删除）资源锁","B":"ReadOnly 资源锁","C":"Azure Policy 的审核效果","D":"移除所有用户的参与者角色"},"a":["A"],"e":"CanNotDelete 锁允许授权用户读取和修改资源，但任何人（包括所有者）都不能删除它——必须先显式移除锁才能删除。这是防止误操作的强力护栏，且锁的效力优先于 RBAC 权限。","r":{"B":"ReadOnly 锁会同时阻止所有修改操作，限制过强，可能影响日常运维（例如无法写入数据或更改配置）。","C":"审核（Audit）效果只记录不合规情况，不会阻止删除动作。","D":"移除角色会影响正常工作，且所有者仍可自行恢复权限，无法可靠防止删除。"},"rt":"锁定资源","ru":"https://learn.microsoft.com/azure/azure-resource-manager/management/lock-resources"},{"id":"D3-015","d":"management-governance","t":"治理与合规：Azure Policy 与资源锁","k":"multi","q":"Azure 资源锁有哪两种类型？（选两项）","o":{"A":"CanNotDelete（删除）","B":"ReadOnly（只读）","C":"NoAccess（禁止访问）","D":"Encrypt（加密）"},"a":["A","B"],"e":"资源锁只有两种：CanNotDelete——可读可改不可删；ReadOnly——只能读，既不能改也不能删（效果相当于对所有人施加只读角色）。锁可应用在订阅、资源组或单个资源上，并向下继承。","r":{"C":"Azure 中没有 NoAccess 类型的资源锁。","D":"加密不是资源锁的类型，而是独立的数据保护功能。"},"rt":"锁定资源","ru":"https://learn.microsoft.com/azure/azure-resource-manager/management/lock-resources"},{"id":"D3-016","d":"management-governance","t":"治理与合规：Azure Policy 与资源锁","k":"truefalse","q":"判断：在资源组上设置的资源锁会被该资源组中的所有资源继承。","o":{"A":"正确","B":"错误"},"a":["A"],"e":"正确。资源锁沿层级继承：订阅上的锁覆盖其下所有资源组和资源，资源组上的锁覆盖其中所有资源。当一个资源受多个锁影响时，最严格的锁生效（ReadOnly 严于 CanNotDelete）。","r":{"B":"继承是资源锁的设计行为，这也是它能高效保护整组资源的原因。"},"rt":"锁定资源","ru":"https://learn.microsoft.com/azure/azure-resource-manager/management/lock-resources"},{"id":"D3-017","d":"management-governance","t":"治理与合规：Purview 与服务信任门户","k":"single","q":"Microsoft Purview 主要解决什么问题？","o":{"A":"统一的数据治理：发现、分类和管理跨本地、多云和 SaaS 的数据资产","B":"虚拟机的自动缩放","C":"网络流量的负载均衡","D":"Azure 费用的预算控制"},"a":["A"],"e":"Microsoft Purview 是统一的数据治理与合规平台：它自动扫描和绘制数据资产地图（Data Map）、建立可搜索的数据目录（Data Catalog）、识别和分类敏感数据（如身份证号、信用卡号），并覆盖本地、多云和 SaaS 数据源，帮助组织回答「我的敏感数据在哪里、谁在用」。","r":{"B":"自动缩放属于计算服务能力。","C":"负载均衡属于网络服务。","D":"预算控制属于 Cost Management。"},"rt":"Microsoft Purview 治理","ru":"https://learn.microsoft.com/purview/purview"},{"id":"D3-018","d":"management-governance","t":"治理与合规：Purview 与服务信任门户","k":"single","q":"审计团队需要获取 Azure 的 ISO 27001 和 SOC 2 审计报告以及合规性文档。应该去哪里获取？","o":{"A":"Azure 门户的「成本分析」页面","B":"服务信任门户（Service Trust Portal）","C":"Azure Advisor","D":"Azure Monitor 日志"},"a":["B"],"e":"服务信任门户是 Microsoft 发布合规性资料的官方站点：独立第三方审计报告（ISO、SOC、FedRAMP 等）、数据保护说明、隐私白皮书和风险评估工具都在这里下载。它回答的是「Microsoft 自己是否合规」，而 Defender for Cloud 的合规仪表板回答的是「你的资源是否合规」。","r":{"A":"成本分析展示的是费用数据，与合规文档无关。","C":"Advisor 提供资源优化建议，不提供审计报告。","D":"Azure Monitor 日志记录的是你自己资源的遥测数据。"},"rt":"服务信任门户","ru":"https://learn.microsoft.com/compliance/regulatory/offering-home"},{"id":"D3-019","d":"management-governance","t":"治理与合规：Azure Policy 与资源锁","k":"single","q":"Azure Policy 的哪种效果（Effect）会在资源不符合规则时阻止其创建？","o":{"A":"Audit（审核）","B":"Deny（拒绝）","C":"Append（追加）","D":"Disabled（已禁用）"},"a":["B"],"e":"Deny 效果在资源创建或更新请求到达 ARM 时直接拒绝不合规的操作，是最强的强制手段。Audit 只记录不合规事件供后续查看；Append/Modify 会自动补充或修改属性；DeployIfNotExists 会自动部署缺失的配套资源。","r":{"A":"Audit 只生成合规性记录和警告，不阻止操作。","C":"Append 是在请求中追加字段（如自动加标记），不会阻止创建。","D":"Disabled 表示该策略分配不生效。"},"rt":"Azure Policy 效果","ru":"https://learn.microsoft.com/azure/governance/policy/concepts/effects"},{"id":"D3-020","d":"management-governance","t":"治理与合规：Azure Policy 与资源锁","k":"single","q":"公司要求所有新建资源必须带有 CostCenter 标记，缺失时自动补上默认值。最合适的机制是？","o":{"A":"资源锁","B":"带 Modify 或 Append 效果的 Azure Policy","C":"RBAC 角色分配","D":"预算警报"},"a":["B"],"e":"Azure Policy 的 Modify/Append 效果可以在资源创建或更新时自动添加缺失的标记，还能通过修正（Remediation）任务批量修复已有资源。这比依赖人工规范可靠得多，也是保证成本分摊数据完整的关键。","r":{"A":"资源锁只能阻止删除或修改，不能添加标记。","C":"RBAC 决定谁能操作资源，无法约束资源必须带哪些属性。","D":"预算警报只在花费达阈值时通知，与标记无关。"},"rt":"Azure Policy 效果","ru":"https://learn.microsoft.com/azure/governance/policy/concepts/effects"},{"id":"D3-021","d":"management-governance","t":"管理工具：门户、CLI、PowerShell 与 Cloud Shell","k":"single","q":"Azure Cloud Shell 的主要特点是什么？","o":{"A":"必须在本地安装才能使用","B":"基于浏览器的交互式 Shell，预装了 Azure CLI 和 Azure PowerShell，无需本地安装","C":"只支持 PowerShell","D":"只能用于查看资源，不能修改"},"a":["B"],"e":"Cloud Shell 是浏览器中的命令行环境：可以在 Bash 和 PowerShell 之间切换，已经预装并自动认证了 Azure CLI、Azure PowerShell 和常用工具（git、terraform 等），并用 Azure 文件共享持久化你的主目录。它让你在任何设备上都能管理 Azure。","r":{"A":"Cloud Shell 运行在云端，不需要本地安装任何东西。","C":"它同时支持 Bash（Azure CLI）和 PowerShell 两种环境。","D":"Cloud Shell 具备完整的管理能力，可以创建、修改和删除资源。"},"rt":"Azure Cloud Shell 概述","ru":"https://learn.microsoft.com/azure/cloud-shell/overview"},{"id":"D3-022","d":"management-governance","t":"管理工具：门户、CLI、PowerShell 与 Cloud Shell","k":"single","q":"Azure CLI 与 Azure PowerShell 的主要区别是？","o":{"A":"Azure CLI 只能在 Windows 上运行","B":"两者功能大体相当，区别在于语法风格：CLI 使用 az 命令，PowerShell 使用 cmdlet（动词-名词）","C":"Azure PowerShell 无法创建资源","D":"Azure CLI 只能查看资源"},"a":["B"],"e":"两者都是跨平台（Windows/Linux/macOS）的命令行管理工具，能力基本对等，选择主要看团队习惯：Azure CLI 是 `az vm create` 这样的风格，更贴近 Bash 脚本；Azure PowerShell 是 `New-AzVM` 这样的动词-名词 cmdlet，输出为对象，便于 PowerShell 管道处理。","r":{"A":"Azure CLI 是跨平台的，Linux 和 macOS 上同样可用。","C":"Azure PowerShell 具备完整的资源管理能力。","D":"Azure CLI 同样可以创建、修改和删除资源。"},"rt":"Azure CLI 概述","ru":"https://learn.microsoft.com/cli/azure/what-is-azure-cli"},{"id":"D3-023","d":"management-governance","t":"管理工具：门户、CLI、PowerShell 与 Cloud Shell","k":"single","q":"Azure 门户（Azure Portal）最适合下列哪种场景？","o":{"A":"大规模重复性的自动化部署","B":"通过图形界面浏览资源、查看仪表板和执行一次性管理操作","C":"在 CI/CD 流水线中自动创建资源","D":"把资源配置纳入版本控制"},"a":["B"],"e":"门户是基于 Web 的图形管理界面，优势是直观、可发现性强，适合探索服务、查看监控仪表板、排查问题和做一次性操作。但它是手工操作，不可重复、不可版本化，因此大规模和自动化场景应改用 CLI/PowerShell 或基础结构即代码。","r":{"A":"手工点击无法规模化，重复部署应使用模板或脚本。","C":"CI/CD 流水线需要可脚本化的接口，门户无法集成。","D":"版本控制需要文本化的定义文件，如 ARM 模板或 Bicep。"},"rt":"Azure 门户概述","ru":"https://learn.microsoft.com/azure/azure-portal/azure-portal-overview"},{"id":"D3-024","d":"management-governance","t":"管理工具：ARM 模板与 Bicep","k":"single","q":"ARM 模板（Azure Resource Manager 模板）的核心特点是什么？","o":{"A":"使用命令式脚本逐步描述操作步骤","B":"使用声明式 JSON 描述目标状态，具备幂等性，可重复部署得到一致结果","C":"只能部署虚拟机","D":"只能在 Azure 门户中手工创建"},"a":["B"],"e":"ARM 模板是声明式的：你描述「最终应该有什么」，而不是「一步步怎么做」，ARM 负责计算差异并并行编排部署。幂等性意味着同一模板重复部署会得到同样的结果，不会重复创建资源——这是基础结构即代码（IaC）的基石。","r":{"A":"命令式描述步骤是脚本（如 CLI 脚本）的做法，模板是声明式的。","C":"ARM 模板可以部署几乎所有 Azure 资源类型。","D":"模板是文本文件，可以纳入 Git 版本控制并通过流水线部署。"},"rt":"ARM 模板概述","ru":"https://learn.microsoft.com/azure/azure-resource-manager/templates/overview"},{"id":"D3-025","d":"management-governance","t":"管理工具：ARM 模板与 Bicep","k":"single","q":"Bicep 相对于 ARM JSON 模板的主要优势是什么？","o":{"A":"语法更简洁易读，且编译后与 ARM 模板等效，支持模块化和类型校验","B":"可以部署到 AWS","C":"不需要 Azure 订阅","D":"运行速度比 ARM 快 10 倍"},"a":["A"],"e":"Bicep 是 Azure 原生的领域特定语言（DSL），用更简洁的语法描述资源（无需大量 JSON 括号和转义），支持模块、参数类型检查和智能提示，最终会转译（transpile）为 ARM 模板由 ARM 执行。它没有引入新的运行时，因此能力与 ARM 完全一致。","r":{"B":"Bicep 是 Azure 专用的，不能部署到其他云（跨云 IaC 可考虑 Terraform）。","C":"部署任何 Azure 资源都需要订阅。","D":"Bicep 最终转译为 ARM 模板执行，部署速度与 ARM 相同，优势在于编写体验。"},"rt":"Bicep 概述","ru":"https://learn.microsoft.com/azure/azure-resource-manager/bicep/overview"},{"id":"D3-026","d":"management-governance","t":"管理工具：门户、CLI、PowerShell 与 Cloud Shell","k":"single","q":"运维人员在外出途中需要用手机查看 Azure 资源状态并重启一台虚拟机。最合适的工具是？","o":{"A":"Azure 移动应用（Azure mobile app）","B":"ARM 模板","C":"Azure Policy","D":"Azure Data Box"},"a":["A"],"e":"Azure 移动应用（iOS/Android）让你在手机上查看资源状态、监控警报、查看服务运行状况，并执行启动/停止/重启虚拟机、重启 Web 应用等常用操作，还内置了 Cloud Shell，适合应急响应。","r":{"B":"ARM 模板用于部署基础结构，不是日常运维操作工具。","C":"Azure Policy 用于合规治理。","D":"Data Box 是数据迁移的物理设备。"},"rt":"Azure 移动应用","ru":"https://learn.microsoft.com/azure/azure-portal/mobile-app/overview"},{"id":"D3-027","d":"management-governance","t":"管理工具：ARM 模板与 Bicep","k":"multi","q":"使用基础结构即代码（IaC）管理 Azure 资源可以带来下列哪两项好处？（选两项）","o":{"A":"配置可以纳入版本控制，变更有迹可循","B":"可以在不同环境中重复部署出完全一致的基础结构","C":"完全消除对 Azure 订阅的需要","D":"自动降低资源的单价"},"a":["A","B"],"e":"IaC 把基础结构定义成文本文件，因而获得软件工程的全部红利：版本控制与代码审查、环境一致性（开发/测试/生产用同一份模板）、可重复与可回滚、以及与 CI/CD 流水线集成实现自动化部署。","r":{"C":"无论怎样部署，都需要 Azure 订阅来承载资源和计费。","D":"资源单价由定价方案决定，与部署方式无关（不过 IaC 有助于避免遗留未清理的资源从而减少浪费）。"},"rt":"ARM 模板概述","ru":"https://learn.microsoft.com/azure/azure-resource-manager/templates/overview"},{"id":"D3-028","d":"management-governance","t":"管理工具：门户、CLI、PowerShell 与 Cloud Shell","k":"single","q":"Azure Arc 在管理与治理方面的作用是？","o":{"A":"把 Azure 的管理能力（Policy、RBAC、标记、监控）扩展到本地、其他云和边缘的资源","B":"自动把本地服务器迁移到 Azure","C":"提供虚拟桌面","D":"生成成本报表"},"a":["A"],"e":"Azure Arc 把非 Azure 资源投射为 Azure 资源对象，从而可以用同一套 Azure 治理工具统一管理：应用 Azure Policy、分配 RBAC、打标记、接入 Azure Monitor 和 Defender for Cloud。这解决了混合与多云环境「工具割裂」的根本痛点。","r":{"B":"迁移工作由 Azure Migrate 负责，Arc 管理的资源仍留在原地。","C":"虚拟桌面是 Azure Virtual Desktop。","D":"成本报表由 Cost Management 生成。"},"rt":"Azure Arc 概述","ru":"https://learn.microsoft.com/azure/azure-arc/overview"},{"id":"D3-029","d":"management-governance","t":"监控：Azure Monitor 与 Application Insights","k":"single","q":"Azure Monitor 的核心作用是什么？","o":{"A":"收集、分析和处理来自云和本地环境的遥测数据（指标与日志），并基于其发出警报","B":"部署虚拟机","C":"管理用户身份","D":"提供数据备份"},"a":["A"],"e":"Azure Monitor 是 Azure 的全栈监控平台：采集指标（Metrics，数值型、近实时）和日志（Logs，结构化事件），提供可视化（仪表板、工作簿）、分析（Log Analytics + KQL 查询）、响应（警报和自动操作），覆盖从基础结构到应用程序的各个层次。","r":{"B":"部署虚拟机是计算服务的职责。","C":"身份管理是 Microsoft Entra ID。","D":"备份由 Azure 备份服务提供。"},"rt":"Azure Monitor 概述","ru":"https://learn.microsoft.com/azure/azure-monitor/overview"},{"id":"D3-030","d":"management-governance","t":"监控：Azure Monitor 与 Application Insights","k":"single","q":"需要对收集到的日志数据运行复杂查询以排查问题。应使用 Azure Monitor 的哪个组件？","o":{"A":"Log Analytics（日志分析）","B":"Application Insights","C":"Azure Advisor","D":"Service Health"},"a":["A"],"e":"Log Analytics 是 Azure Monitor 中用于编写和运行日志查询的工具，使用 Kusto 查询语言（KQL）对存放在 Log Analytics 工作区的数据做筛选、聚合、关联和可视化。它是深入排查问题的主力工具。","r":{"B":"Application Insights 专注于应用程序性能监控（APM），其数据同样可以用 KQL 查询，但题目问的是通用的日志查询组件。","C":"Advisor 提供的是优化建议，不是日志查询工具。","D":"Service Health 报告的是 Azure 平台的服务状况，不用于查询自有日志。"},"rt":"Log Analytics 概述","ru":"https://learn.microsoft.com/azure/azure-monitor/logs/log-analytics-overview"},{"id":"D3-031","d":"management-governance","t":"监控：Azure Monitor 与 Application Insights","k":"single","q":"开发团队希望监控 Web 应用的响应时间、失败请求率和依赖项调用情况，并做用户行为分析。应使用什么？","o":{"A":"Application Insights","B":"Azure Advisor","C":"Azure Policy","D":"Azure Service Health"},"a":["A"],"e":"Application Insights 是 Azure Monitor 中的应用程序性能管理（APM）功能：自动采集请求速率与响应时间、失败率、依赖项（数据库/外部 API）调用、异常堆栈，并提供实时指标流、应用程序映射和用户行为分析（漏斗、留存）。","r":{"B":"Advisor 给出的是资源配置层面的优化建议，不采集应用性能遥测。","C":"Azure Policy 是治理工具，与应用监控无关。","D":"Service Health 报告的是 Azure 平台自身的服务事件。"},"rt":"Application Insights 概述","ru":"https://learn.microsoft.com/azure/azure-monitor/app/app-insights-overview"},{"id":"D3-032","d":"management-governance","t":"监控：Advisor 与 Service Health","k":"single","q":"Azure Advisor 提供的建议覆盖哪些类别？","o":{"A":"只有成本","B":"可靠性、安全性、性能、成本和卓越运营五大类","C":"只有安全性和性能","D":"只有合规性"},"a":["B"],"e":"Azure Advisor 是个性化的云顾问，基于你实际的资源使用情况给出五类建议：可靠性（Reliability）、安全性（Security）、性能（Performance）、成本（Cost）和卓越运营（Operational Excellence）。这五类对应 Azure 架构良好框架的支柱。","r":{"A":"成本只是五个类别之一。","C":"遗漏了可靠性、成本和卓越运营三类。","D":"合规性由 Azure Policy 和 Defender for Cloud 的合规仪表板负责，不是 Advisor 的类别。"},"rt":"Azure Advisor 概述","ru":"https://learn.microsoft.com/azure/advisor/advisor-overview"},{"id":"D3-033","d":"management-governance","t":"监控：Advisor 与 Service Health","k":"single","q":"需要了解某个 Azure 服务是否正在发生中断、是否有计划内维护会影响自己的资源。应使用什么？","o":{"A":"Azure Service Health","B":"Azure Advisor","C":"Azure Monitor 指标","D":"Azure Policy"},"a":["A"],"e":"Azure Service Health 提供针对「你所使用的服务和区域」的个性化健康信息，包含三类事件：服务问题（正在发生的中断）、计划内维护、健康公告（如即将弃用的功能）。你还可以基于它配置警报，在事件发生时收到通知。","r":{"B":"Advisor 提供优化建议，不报告平台故障。","C":"Azure Monitor 指标反映的是你自己资源的运行数据，不解释平台级中断原因。","D":"Azure Policy 是合规治理工具。"},"rt":"Azure Service Health 概述","ru":"https://learn.microsoft.com/azure/service-health/overview"},{"id":"D3-034","d":"management-governance","t":"监控：Advisor 与 Service Health","k":"single","q":"Azure 状态（Azure Status）、Service Health 和资源运行状况（Resource Health）三者的区别是？","o":{"A":"三者完全相同","B":"Azure 状态展示全球所有区域所有服务的整体状况；Service Health 针对你使用的服务和区域做个性化通知；资源运行状况报告你单个资源的健康状态","C":"只有 Azure 状态可以配置警报","D":"资源运行状况用于展示全球服务状态"},"a":["B"],"e":"三者是从「全球 → 你的订阅 → 单个资源」逐级聚焦的关系：Azure 状态是面向所有人的全球公告页；Service Health 只告诉你与自己订阅相关的事件；资源运行状况则回答「我这一台虚拟机现在是否健康、为什么不可用」。","r":{"A":"三者的范围和用途各不相同。","C":"Service Health 和资源运行状况都支持配置警报，Azure 状态是公开页面。","D":"资源运行状况只针对单个资源，不展示全球状态。"},"rt":"Azure Service Health 概述","ru":"https://learn.microsoft.com/azure/service-health/overview"},{"id":"D3-035","d":"management-governance","t":"监控：Azure Monitor 与 Application Insights","k":"single","q":"Azure Monitor 中的「指标（Metrics）」与「日志（Logs）」的主要区别是什么？","o":{"A":"指标是数值型、按时间序列采集的轻量数据，近实时；日志是结构化的事件记录，适合复杂查询和长期保留","B":"指标只能用于虚拟机，日志只能用于应用","C":"两者完全相同","D":"日志不能用于触发警报"},"a":["A"],"e":"指标是时间序列数值（如 CPU 百分比、请求数），采集开销小、延迟低，适合实时监控和快速告警；日志是带有丰富属性的事件记录，存放在 Log Analytics 工作区，用 KQL 做复杂分析。两者都可以触发警报，只是适用场景不同。","r":{"B":"两者都适用于各类资源，不存在这种限制。","C":"二者的数据结构、存储方式和查询方式都不同。","D":"日志查询同样可以配置日志警报规则。"},"rt":"Azure Monitor 概述","ru":"https://learn.microsoft.com/azure/azure-monitor/overview"},{"id":"D3-036","d":"management-governance","t":"监控：Azure Monitor 与 Application Insights","k":"single","q":"当虚拟机 CPU 使用率连续 5 分钟超过 90% 时自动发送邮件通知运维团队。应配置什么？","o":{"A":"Azure Monitor 警报规则与操作组","B":"Azure Policy 分配","C":"资源锁","D":"Azure Advisor 建议"},"a":["A"],"e":"在 Azure Monitor 中创建警报规则：定义监视目标（该虚拟机）、条件（CPU 百分比 > 90%，聚合窗口 5 分钟），并关联操作组（Action Group）来定义响应动作——发邮件、发短信、调用 Webhook 或触发 Logic App/Function 自动修复。","r":{"B":"Azure Policy 评估的是资源配置合规性，不监控运行指标。","C":"资源锁用于防止删除和修改。","D":"Advisor 只是周期性给出建议，不能按阈值实时告警。"},"rt":"Azure Monitor 警报","ru":"https://learn.microsoft.com/azure/azure-monitor/alerts/alerts-overview"},{"id":"D3-037","d":"management-governance","t":"监控：Advisor 与 Service Health","k":"single","q":"Azure Advisor 发现某台虚拟机长期 CPU 使用率低于 5%，最可能给出什么类别的建议？","o":{"A":"成本建议：调整虚拟机规格或关停以节省费用","B":"安全建议：启用 MFA","C":"可靠性建议：增加副本","D":"性能建议：升级到更大的规格"},"a":["A"],"e":"长期低利用率意味着为闲置容量付费，Advisor 会把它列为成本优化建议，提示「调整大小（right-size）或关闭」该虚拟机。识别闲置和超配资源是云成本治理中最常见、见效最快的动作。","r":{"B":"MFA 属于安全建议，与 CPU 利用率无关。","C":"低利用率不是可靠性问题，增加副本只会进一步增加浪费。","D":"利用率低说明规格已经过剩，升级规格与事实相反。"},"rt":"Azure Advisor 概述","ru":"https://learn.microsoft.com/azure/advisor/advisor-overview"},{"id":"D3-038","d":"management-governance","t":"监控：Azure Monitor 与 Application Insights","k":"truefalse","q":"判断：Azure Monitor 只能监控 Azure 中的资源，无法监控本地服务器。","o":{"A":"正确","B":"错误"},"a":["B"],"e":"错误。通过安装 Azure Monitor 代理（AMA）或借助 Azure Arc，Azure Monitor 同样可以采集本地服务器和其他云上虚拟机的指标与日志，实现混合环境的统一监控。这正是混合云可观测性的常见做法。","r":{"A":"这是常见误区。Azure Monitor 支持混合与多云监控，不局限于 Azure 内的资源。"},"rt":"Azure Monitor 概述","ru":"https://learn.microsoft.com/azure/azure-monitor/overview"},{"id":"D3-039","d":"management-governance","t":"成本管理：计算器与 Cost Management","k":"single","q":"Cost Management 中的「成本分析（Cost analysis）」主要用于？","o":{"A":"预估尚未部署资源的费用","B":"按订阅、资源组、服务或标记等维度查看和分解已经产生的实际费用","C":"自动优化应用代码","D":"检查资源是否符合安全基线"},"a":["B"],"e":"成本分析是「回看」工具：按时间、订阅、资源组、资源类型、位置或标记等维度切分已发生的费用，识别花钱最多的资源和异常增长趋势。要「前瞻」估算未部署资源的费用应使用定价计算器。","r":{"A":"预估未部署资源费用是定价计算器的职责。","C":"代码优化不属于成本管理工具的能力。","D":"安全基线检查由 Defender for Cloud 完成。"},"rt":"Azure 成本管理概述","ru":"https://learn.microsoft.com/azure/cost-management-billing/costs/overview-cost-management"},{"id":"D3-040","d":"management-governance","t":"治理与合规：Azure Policy 与资源锁","k":"single","q":"某订阅中已有 200 台虚拟机未打标记。刚刚创建的 Azure Policy 要求必须有 Environment 标记。如何让已有资源也符合要求？","o":{"A":"策略会自动立即修改所有已有资源","B":"创建修正（Remediation）任务，对已有的不合规资源批量应用策略效果","C":"必须删除并重建所有虚拟机","D":"已有资源永远无法被策略管理"},"a":["B"],"e":"Azure Policy 对新建/更新的资源实时生效，但对存量资源只是标记为「不合规」。要真正修复存量资源，需要为 DeployIfNotExists 或 Modify 类策略创建修正任务，由策略的托管标识批量执行变更。","r":{"A":"策略不会自动修改存量资源，必须显式触发修正任务。","C":"删除重建是极端且不必要的做法，修正任务即可解决。","D":"存量资源会被持续评估合规性，并可通过修正任务治理。"},"rt":"策略修正","ru":"https://learn.microsoft.com/azure/governance/policy/how-to/remediate-resources"},{"id":"D3-041","d":"management-governance","t":"成本管理：影响因素与优化","k":"single","q":"下列哪种虚拟机定价方式最适合可以被随时中断的批处理作业，并能获得最大折扣？","o":{"A":"即用即付","B":"预留实例","C":"现成（Spot）虚拟机","D":"专用主机"},"a":["C"],"e":"Spot 虚拟机使用 Azure 的闲置容量，价格极低（可低至按需价格的一小部分），但当 Azure 需要回收容量时会被驱逐（提前 30 秒通知）。因此只适合可中断、可重试的工作负载，如批量渲染、大规模测试和数据处理。","r":{"A":"即用即付没有折扣，价格最高。","B":"预留实例需要承诺 1 或 3 年，适合长期稳定负载而不是临时批处理。","D":"专用主机提供物理服务器隔离，价格更高，用于合规和许可场景。"},"rt":"Azure Spot 虚拟机","ru":"https://learn.microsoft.com/azure/virtual-machines/spot-vms"},{"id":"D3-042","d":"management-governance","t":"监控：Advisor 与 Service Health","k":"multi","q":"下列哪两项可以帮助组织主动发现 Azure 环境中的安全风险？（选两项）","o":{"A":"Microsoft Defender for Cloud 的安全分数与建议","B":"Azure Advisor 的安全建议","C":"Azure 定价计算器","D":"资源锁"},"a":["A","B"],"e":"Defender for Cloud 持续评估资源配置并以安全分数量化态势、给出修复步骤；Azure Advisor 的安全类别建议实际上就来自 Defender for Cloud。两者都是「主动发现风险」的工具。","r":{"C":"定价计算器只用于费用估算，与安全无关。","D":"资源锁是防止误删误改的护栏，属于被动保护措施，不能发现风险。"},"rt":"Azure Advisor 概述","ru":"https://learn.microsoft.com/azure/advisor/advisor-overview"},{"id":"D3-043","d":"management-governance","t":"管理工具：门户、CLI、PowerShell 与 Cloud Shell","k":"single","q":"关于 Azure 门户、CLI、PowerShell 和 REST API 的关系，下列说法正确的是？","o":{"A":"它们互相独立，产生的结果可能不一致","B":"它们最终都通过 Azure Resource Manager 执行操作，因此结果一致","C":"只有门户可以创建资源","D":"REST API 只能读取不能写入"},"a":["B"],"e":"所有管理工具都是 ARM 的客户端：请求统一经过 ARM 进行身份验证、RBAC 授权和策略评估，再交给资源提供程序。这保证了无论用哪个工具，同样的操作会得到同样的结果，也让权限和策略无法通过换工具绕过。","r":{"A":"统一经由 ARM 正是为了保证一致性。","C":"CLI、PowerShell、REST API、SDK 同样可以创建资源。","D":"REST API 支持完整的创建、更新和删除操作。"},"rt":"Azure Resource Manager 概述","ru":"https://learn.microsoft.com/azure/azure-resource-manager/management/overview"},{"id":"D3-044","d":"management-governance","t":"监控：Azure Monitor 与 Application Insights","k":"single","q":"Azure Monitor 中的「操作组（Action Group）」定义的是什么？","o":{"A":"触发警报的条件","B":"警报触发后要执行的通知和操作集合（邮件、短信、Webhook、自动化等）","C":"资源的访问权限","D":"资源的部署顺序"},"a":["B"],"e":"警报规则回答「什么时候告警」，操作组回答「告警后做什么」：给谁发邮件/短信/推送、调用哪个 Webhook、触发哪个 Logic App、Function 或 Runbook 做自动修复。操作组可被多个警报规则复用。","r":{"A":"触发条件定义在警报规则中，不在操作组。","C":"访问权限由 RBAC 管理。","D":"部署顺序由 ARM 模板的依赖关系决定。"},"rt":"Azure Monitor 警报","ru":"https://learn.microsoft.com/azure/azure-monitor/alerts/alerts-overview"},{"id":"D3-045","d":"management-governance","t":"治理与合规：Purview 与服务信任门户","k":"single","q":"组织需要在 Azure 中自动发现哪些存储中含有身份证号、银行卡号等敏感信息，并进行分类标注。应使用什么？","o":{"A":"Microsoft Purview","B":"Azure Monitor","C":"Azure Policy","D":"Azure Advisor"},"a":["A"],"e":"Microsoft Purview 的数据映射和分类能力可以自动扫描数据源，用内置或自定义分类器识别敏感信息类型（身份证、信用卡、健康信息等）并打上分类标签，从而回答「敏感数据在哪里」这个数据治理的首要问题。","r":{"B":"Azure Monitor 采集的是运行遥测数据，不扫描数据内容。","C":"Azure Policy 评估资源配置属性，不检查数据内容。","D":"Advisor 给出的是资源优化建议。"},"rt":"Microsoft Purview 治理","ru":"https://learn.microsoft.com/purview/purview"},{"id":"D3-046","d":"management-governance","t":"成本管理：影响因素与优化","k":"single","q":"下列哪项做法无法降低 Azure 成本？","o":{"A":"对开发测试环境的虚拟机在非工作时间自动关机","B":"为长期稳定的工作负载购买预留实例","C":"把所有资源都部署到尽可能多的区域","D":"删除未挂载的孤立磁盘和未使用的公共 IP"},"a":["C"],"e":"多区域部署会成倍增加资源数量并产生跨区域流量费用，属于为可用性付出的成本，而不是降本手段。真正常见的降本动作包括：非工作时间关机、预留实例/节省计划、调整规格、清理孤立资源、使用 Spot 虚拟机和混合权益。","r":{"A":"开发测试环境夜间和周末关机通常能直接省下 60% 以上的计算费用。","B":"预留实例对稳定负载可节省高达约 72%。","D":"孤立磁盘和保留的公共 IP 会持续计费，清理它们是典型的快速降本动作。"},"rt":"Azure 成本管理概述","ru":"https://learn.microsoft.com/azure/cost-management-billing/costs/overview-cost-management"},{"id":"D3-047","d":"management-governance","t":"治理与合规：Azure Policy 与资源锁","k":"single","q":"「合规性」在 Azure 中由多个工具共同支撑。下列哪个工具用于查看「你自己的资源」相对于某个法规标准（如 ISO 27001）的合规状态？","o":{"A":"服务信任门户","B":"Microsoft Defender for Cloud 的法规合规性仪表板","C":"Azure 定价计算器","D":"Azure 移动应用"},"a":["B"],"e":"区分两个方向：服务信任门户回答「Microsoft 的云平台是否通过了某项认证」，提供审计报告下载；Defender for Cloud 的法规合规性仪表板回答「我部署的资源当前是否满足某项标准的控制要求」，并列出具体的不合规项和修复方法。","r":{"A":"服务信任门户提供的是 Microsoft 自身的审计报告，不评估你的资源。","C":"定价计算器与合规无关。","D":"移动应用只是管理界面，不提供合规评估。"},"rt":"法规合规性仪表板","ru":"https://learn.microsoft.com/azure/defender-for-cloud/regulatory-compliance-dashboard"},{"id":"D3-048","d":"management-governance","t":"管理工具：门户、CLI、PowerShell 与 Cloud Shell","k":"truefalse","q":"判断：Azure Cloud Shell 需要在首次使用时关联一个 Azure 存储账户，用于持久保存文件。","o":{"A":"正确","B":"错误"},"a":["A"],"e":"正确。Cloud Shell 会话本身是临时的，为了在会话之间保留脚本和文件，首次启动时会提示创建或选择一个存储账户，并在其中创建文件共享挂载为主目录（clouddrive）。该存储账户会产生少量存储费用。","r":{"B":"没有持久化存储，Cloud Shell 会话结束后文件就会丢失，因此需要关联存储账户。"},"rt":"Azure Cloud Shell 概述","ru":"https://learn.microsoft.com/azure/cloud-shell/overview"},{"id":"D3-049","d":"management-governance","t":"监控：Azure Monitor 与 Application Insights","k":"single","q":"Azure 中用于查询 Log Analytics 工作区数据的查询语言是？","o":{"A":"SQL","B":"Kusto 查询语言（KQL）","C":"GraphQL","D":"XPath"},"a":["B"],"e":"Log Analytics 使用 Kusto 查询语言（KQL）。它是只读的、管道式的查询语言，语法类似 `Heartbeat | where TimeGenerated > ago(1h) | summarize count() by Computer`，专为大规模日志和时序数据的快速分析设计。","r":{"A":"SQL 用于关系型数据库，不是 Log Analytics 的查询语言。","C":"GraphQL 是 API 查询语言，与日志分析无关。","D":"XPath 用于 XML 文档定位。"},"rt":"Log Analytics 概述","ru":"https://learn.microsoft.com/azure/azure-monitor/logs/log-analytics-overview"},{"id":"D3-050","d":"management-governance","t":"成本管理：影响因素与优化","k":"single","q":"关于 Azure 免费账户，下列说法正确的是？","o":{"A":"永久免费使用所有 Azure 服务","B":"提供有限期的试用额度和一组在 12 个月内免费的热门服务，以及始终免费的服务层","C":"只能使用虚拟机","D":"需要先签订企业协议"},"a":["B"],"e":"Azure 免费账户包含三部分：一笔在 30 天内使用的试用额度、一组在 12 个月内免费的热门服务（有用量上限），以及一批「始终免费」的服务层（如一定额度的 Functions 调用）。超出额度后按标准价格计费。","r":{"A":"免费额度有明确的时间和用量上限，不是永久免费使用全部服务。","C":"免费账户可以使用多种服务，不限于虚拟机。","D":"个人用信用卡验证即可注册，不需要企业协议。"},"rt":"Azure 免费账户","ru":"https://learn.microsoft.com/azure/cost-management-billing/manage/avoid-charges-free-account"},{"id":"D3-051","d":"management-governance","t":"监控：Advisor 与 Service Health","k":"single","q":"Azure 中用于查看「某一台特定虚拟机当前是否可用，以及不可用是由平台事件还是用户操作导致」的功能是？","o":{"A":"资源运行状况（Resource Health）","B":"Azure 状态页","C":"Azure Advisor","D":"成本分析"},"a":["A"],"e":"资源运行状况针对单个资源给出「可用 / 不可用 / 降级 / 未知」的状态，并说明原因分类——平台启动的事件（如主机故障、计划维护）还是用户启动的操作（如自己关机）。这对区分「是 Azure 的问题还是我们自己的问题」非常关键。","r":{"B":"Azure 状态页展示的是全球范围的大规模服务中断，不针对单个资源。","C":"Advisor 提供的是优化建议，不报告实时可用性。","D":"成本分析展示的是费用数据。"},"rt":"资源运行状况","ru":"https://learn.microsoft.com/azure/service-health/resource-health-overview"},{"id":"D3-052","d":"management-governance","t":"成本管理：计算器与 Cost Management","k":"single","q":"使用定价计算器时，下列哪项会直接影响估算结果？","o":{"A":"选择的区域和资源规格","B":"资源组的名称","C":"订阅的显示语言","D":"使用门户还是 CLI 部署"},"a":["A"],"e":"定价计算器的估算基于：服务类型、规格（如虚拟机大小）、数量、运行时长、区域（不同区域单价不同）、冗余选项和许可方式。命名、界面语言和部署工具都不影响价格。","r":{"B":"资源命名与计费无关。","C":"语言设置只影响界面显示。","D":"部署工具不同不会改变资源单价。"},"rt":"定价计算器","ru":"https://learn.microsoft.com/azure/cost-management-billing/understand/pricing-calculator"},{"id":"D3-053","d":"management-governance","t":"治理与合规：Azure Policy 与资源锁","k":"single","q":"下列哪项最准确地描述了 Azure 中「治理（Governance）」要解决的核心问题？","o":{"A":"确保资源的部署和使用符合组织的标准、预算和法规要求，并可持续审计","B":"提高应用程序的运行速度","C":"减少虚拟机的启动时间","D":"自动编写基础结构代码"},"a":["A"],"e":"治理的目标是「在保持敏捷的同时不失控」：用管理组和订阅划分边界，用 Azure Policy 强制标准，用 RBAC 控制权限，用标记和 Cost Management 管住预算，用资源锁防止误操作，用 Defender for Cloud 和 Purview 持续证明合规。","r":{"B":"性能优化属于架构与调优范畴，不是治理的核心目标。","C":"启动时间属于性能指标。","D":"编写基础结构代码是实现手段，不是治理本身的目标。"},"rt":"Azure 治理","ru":"https://learn.microsoft.com/azure/governance/"},{"id":"D3-054","d":"management-governance","t":"监控：Advisor 与 Service Health","k":"single","q":"组织希望在 Azure 计划对其使用的区域执行维护前收到通知。应配置什么？","o":{"A":"基于 Azure Service Health 的警报","B":"Azure Advisor 建议","C":"预算警报","D":"资源锁"},"a":["A"],"e":"Service Health 覆盖三类事件，其中「计划内维护」正是本题场景。你可以针对订阅、区域和服务创建 Service Health 警报规则，并关联操作组，在事件发布时通过邮件、短信或 Webhook 通知相关团队提前准备。","r":{"B":"Advisor 提供的是优化建议，不发布维护通知。","C":"预算警报只与花费有关。","D":"资源锁是防误删机制。"},"rt":"Azure Service Health 概述","ru":"https://learn.microsoft.com/azure/service-health/overview"},{"id":"D3-055","d":"management-governance","t":"管理工具：门户、CLI、PowerShell 与 Cloud Shell","k":"multi","q":"下列哪两项属于 Azure 中的「基础结构即代码」工具？（选两项）","o":{"A":"ARM 模板","B":"Bicep","C":"Azure 门户","D":"Azure 移动应用"},"a":["A","B"],"e":"ARM 模板（JSON）和 Bicep（DSL）都是声明式的基础结构即代码工具：定义写在文本文件里，可以版本控制、代码审查、在流水线中自动部署并保证幂等。（第三方的 Terraform 也属于此类，但不是 Azure 原生工具。）","r":{"C":"Azure 门户是图形界面手工操作，不可版本控制、不可重复。","D":"移动应用是运维查看和应急操作工具，与代码化部署无关。"},"rt":"ARM 模板概述","ru":"https://learn.microsoft.com/azure/azure-resource-manager/templates/overview"},{"id":"D3-056","d":"management-governance","t":"监控：Azure Monitor 与 Application Insights","k":"single","q":"需要把 Azure 虚拟机的性能数据、应用日志以及本地服务器日志汇总到一处进行统一分析。应使用什么？","o":{"A":"Log Analytics 工作区","B":"Azure Blob 存储的存档层","C":"Azure 队列存储","D":"定价计算器"},"a":["A"],"e":"Log Analytics 工作区是 Azure Monitor 日志数据的存储和分析容器：通过 Azure Monitor 代理可以把 Azure 资源、本地服务器和其他云上虚拟机的日志与性能数据统一发送到同一个工作区，然后用 KQL 做跨源关联分析。","r":{"B":"存档层适合长期不访问的归档数据，无法直接查询分析。","C":"队列存储用于异步消息传递，不是日志分析平台。","D":"定价计算器用于费用估算。"},"rt":"Log Analytics 概述","ru":"https://learn.microsoft.com/azure/azure-monitor/logs/log-analytics-overview"},{"id":"D3-057","d":"management-governance","t":"成本管理：影响因素与优化","k":"single","q":"下列哪种订阅/账户结构最适合把不同部门的 Azure 花费清晰分开结算？","o":{"A":"所有部门共用一个订阅和一个资源组","B":"为每个部门创建独立的订阅（或至少用标记与资源组严格区分）","C":"为每个部门创建独立的 Entra 租户","D":"让每个部门各自注册免费账户"},"a":["B"],"e":"订阅是计费边界，按部门拆分订阅可以直接得到分离的账单，管理上再用管理组统一施加策略。如果不便拆分订阅，则至少要通过资源组划分 + 强制标记（用 Azure Policy 保证标记完整）来实现成本分摊。","r":{"A":"混在一起后无法清晰归集成本，也难以分别授权。","C":"拆分租户会造成身份割裂和巨大管理负担，属于过度设计。","D":"免费账户有额度限制，不适合承载生产负载，也无法统一治理。"},"rt":"Azure 成本管理概述","ru":"https://learn.microsoft.com/azure/cost-management-billing/costs/overview-cost-management"},{"id":"D3-058","d":"management-governance","t":"治理与合规：Azure Policy 与资源锁","k":"single","q":"某资源同时被订阅级别的 ReadOnly 锁和资源组级别的 CanNotDelete 锁覆盖。实际生效的是什么？","o":{"A":"CanNotDelete，因为它更靠近资源","B":"ReadOnly，因为多个锁中最严格的生效","C":"两个锁互相抵消，都不生效","D":"随机生效一个"},"a":["B"],"e":"当资源继承到多个锁时，最严格（most restrictive）的锁生效。ReadOnly 严于 CanNotDelete，因此该资源既不能修改也不能删除。这一点与 RBAC 的「就近覆盖」直觉不同，是常见的考点陷阱。","r":{"A":"锁不遵循「就近优先」，而是「最严格优先」。","C":"多个锁会叠加，不会互相抵消。","D":"生效规则是确定的，不存在随机性。"},"rt":"锁定资源","ru":"https://learn.microsoft.com/azure/azure-resource-manager/management/lock-resources"},{"id":"D3-059","d":"management-governance","t":"监控：Advisor 与 Service Health","k":"single","q":"Azure Advisor 的建议是基于什么生成的？","o":{"A":"通用的行业最佳实践清单，与实际使用情况无关","B":"对你实际部署的资源配置和使用遥测数据的分析，因此是个性化的","C":"其他客户的配置","D":"随机抽样"},"a":["B"],"e":"Advisor 会分析你订阅中资源的实际配置和使用情况（如利用率、冗余设置、安全配置），据此生成针对性的建议并按影响程度分级。因为是个性化的，所以不同订阅看到的建议完全不同。","r":{"A":"如果只是通用清单就失去了「顾问」的意义，Advisor 明确是个性化的。","C":"Advisor 不会基于其他客户的数据生成你的建议。","D":"建议基于确定性的分析规则，不是随机产生。"},"rt":"Azure Advisor 概述","ru":"https://learn.microsoft.com/azure/advisor/advisor-overview"},{"id":"D3-060","d":"management-governance","t":"成本管理：计算器与 Cost Management","k":"single","q":"关于 Microsoft Cost Management 的使用范围，下列说法正确的是？","o":{"A":"只能查看 Azure 的费用","B":"可以查看 Azure 的费用，并且支持查看已连接的 AWS 等其他云的费用","C":"只能查看单个资源组的费用","D":"必须购买额外许可才能使用"},"a":["B"],"e":"Cost Management 主要用于 Azure 成本治理，同时支持连接 AWS 账户以在同一界面中查看和分析多云成本（该跨云功能可能产生额外费用）。对 Azure 使用而言，Cost Management 本身是免费的。","r":{"A":"它支持连接其他云进行多云成本可见性管理。","C":"它支持管理组、订阅、资源组等多种范围。","D":"针对 Azure 用量使用 Cost Management 不额外收费。"},"rt":"Azure 成本管理概述","ru":"https://learn.microsoft.com/azure/cost-management-billing/costs/overview-cost-management"}];